// Üretilen dosya: tool/ozgun/uret.py. Mühendislik ve Tasarım · Tasarım süreci, malzeme bilgisi, ölçme ve mühendislik etiği (orta).
const ozEngineering4Orta = <(String, String, List<String>, String)>[
  ('Bir belediye \'parkta oturacak yer yok\' şikâyetini alıyor. Bir mühendisin problemi iyi tanımlamış sayılması için hangi ifadeyi kullanması en uygundur?', 'Günde yaklaşık 200 kişiye gölgeli, dayanıklı oturma yeri sağlanmalı', ['Parka ahşap bank konulmalı', 'En ucuz bank satın alınmalı', 'Bank tasarımı yurt dışından hazır olarak satın alınıp parka getirilmeli'], 'İyi bir problem tanımı çözümü önceden dayatmaz; ihtiyacı ölçülebilir biçimde ifade eder. Diğer seçenekler doğrudan bir çözüm ya da yöntem önerir.'),
  ('Bir çanta tasarımında \'kütle 1,2 kg\'ı geçmemeli\' ve \'olabildiğince şık görünmeli\' ifadeleri yer alıyor. Bu ifadeler için hangi sınıflama doğrudur?', 'Birincisi kısıt, ikincisi ölçüt', ['Birincisi ölçüt, ikincisi kısıt', 'İkisi de kısıt', 'İkisi de varsayım'], 'Kesin sayısal üst sınır bir kısıttır; \'olabildiğince\' ile ifade edilen ve seçenekleri sıralamaya yarayan nitelik ise bir ölçüttür.'),
  ('SCAMPER tekniğindeki \'S\' harfi hangi soruyu çağrıştırır?', 'Neyin yerine başka bir şey konabilir?', ['Ne büyütülebilir?', 'Ne tamamen kaldırılabilir ya da sadeleştirilebilir?', 'Ne tersine çevrilebilir?'], 'SCAMPER\'da S, İngilizce \'Substitute\' yani yerine koyma anlamına gelir; diğerleri Magnify, Eliminate ve Reverse adımlarına karşılık gelir.'),
  ('Bir tasarımcı, bir ürünün işlevlerini satırlara, her işlev için olası çözümleri sütunlara yazıp kombinasyonlar oluşturuyor. Kullandığı yöntem hangisidir?', 'Morfolojik tablo', ['Gantt şeması', 'Pareto analizi', 'Balık kılçığı şeması'], 'Morfolojik tablo (Zwicky kutusu), alt işlevler için seçenekleri sistematik olarak birleştirerek yeni kavramlar üretmeye yarar.'),
  ('Pugh yönteminde kavramlar nasıl değerlendirilir?', 'Referansa göre artı, eksi ya da aynı', ['Rastgele seçilen bir jüri oyuyla', 'Yalnız üretim maliyetine göre', 'Yalnız müşteri anketine ve satış beklentisine göre'], 'Pugh kavram seçiminde bir kavram referans (datum) alınır ve diğerleri her ölçütte ondan daha iyi, daha kötü ya da aynı diye işaretlenir.'),
  ('Bir ekip, tasarımın yalnızca menteşe mekanizmasının çalışıp çalışmadığını görmek için kaba bir düzenek yapıyor. Bu yaklaşımın en önemli yararı nedir?', 'Riskli bir belirsizliği ucuza gidermek', ['Ürünün son görünümünü ve rengini müşteriye sunmak', 'Seri üretim kalıbını doğrulamak', 'Ambalaj tasarımını tamamlamak'], 'Belirli bir soruyu yanıtlayan basit prototipler, en riskli varsayımı pahalı kararlar alınmadan önce sınar.'),
  ('Aşağıdaki durumlardan hangisi daha büyük bir güvenlik katsayısı seçmeyi en çok haklı çıkarır?', 'Belirsiz yükler ve can kaybı riski', ['Malzeme özelliklerinin iyi bilinmesi', 'Parçanın kütlesinin kritik olması', 'Arızanın kullanıcıya yalnız küçük bir rahatsızlık yaratması'], 'Yük ve malzeme belirsizliği ile arızanın ağır sonuçları büyük güvenlik katsayısını gerektirir; kütlenin kritik olduğu durumlarda ise katsayı olabildiğince düşük tutulmaya çalışılır.'),
  ('Güvenilirliği 0,8 olan iki özdeş bileşen paralel (yedekli) bağlanıyor. Bağımsızlık varsayımıyla sistem güvenilirliği kaçtır?', '0,96', ['0,64', '0,80', '1,60'], 'Paralel sistem ancak ikisi birden arızalanırsa çalışmaz: 1 − 0,2 × 0,2 = 0,96.'),
  ('Bir ürünün arıza oranının zamana göre grafiği klasik olarak hangi adla anılır?', 'Küvet eğrisi', ['Çan eğrisi', 'Öğrenme eğrisi', 'S eğrisi'], 'Küvet eğrisinde başta erken arızalar, ortada düşük ve sabit rastgele arızalar, sonda aşınma arızaları görülür.'),
  ('Bir kapı kolu yüksekliği, kullanıcıların 5. ile 95. yüzdelik dilimleri arasını kapsayacak biçimde seçiliyor. Bu yaklaşımın amacı nedir?', 'Kullanıcıların çoğuna uyması', ['Yalnız ortalama boydaki tek bir kişiye tam uymak', 'Yalnız en uzun kişiye uymak', 'Malzeme miktarını en aza indirmek'], 'Ortalama kişi için tasarım çoğu kişiyi dışarıda bırakabilir; 5–95 yüzdelik aralığı nüfusun yaklaşık %90\'ını kapsar.'),
  ('Ocakta düğmelerin, kontrol ettikleri gözlerle aynı uzamsal düzende yerleştirilmesi hangi tasarım ilkesine örnektir?', 'Doğal eşleme', ['Gizli işlev', 'Kalıcı kusur', 'Bilişsel yük artırma'], 'Don Norman\'ın vurguladığı doğal eşlemede kumandanın konumu etkilediği öğeyle sezgisel olarak eşleşir ve kullanım hataları azalır.'),
  ('\'Beşikten beşiğe\' (cradle to cradle) tasarım anlayışı neyi hedefler?', 'Malzemelerin yeniden döngüye girmesini', ['Ürünlerin tek kullanımlık olmasını', 'Atıkların düzenli depolama alanlarına güvenle gönderilmesini', 'Ürün ömrünün bilerek kısaltılmasını'], 'Bu yaklaşımda atık kavramı ortadan kaldırılmak istenir; malzemeler biyolojik ya da teknik döngülerde yeniden kullanılır.'),
  ('Bir elektrikli süpürgede vidalar yerine geçmeli bağlantı kullanıp farklı plastikleri işaretlemek, öncelikle hangi tasarım yaklaşımına hizmet eder?', 'Söküm ve geri dönüşüm için tasarım', ['Planlı eskitme', 'Görünüm için tasarım', 'Ağırlık artırarak sağlamlık hissi verme'], 'Kolay sökülen ve malzeme türü belli parçalar ömür sonunda ayrıştırmayı ve geri dönüşümü kolaylaştırır.'),
  ('İç yapısı karmaşık bir parçanın resminde kesit görünüşü kullanılmasının temel nedeni nedir?', 'İç ayrıntıları açıkça göstermek', ['Parçanın rengini belirtmek', 'Resim kâğıdından ve çizim süresinden tasarruf etmek', 'Malzemenin fiyatını göstermek'], 'Hayali bir düzlemle kesilen parça, iç boşluk ve delikleri tam çizgilerle ve taramayla net biçimde gösterir.'),
  ('Delik 30,000–30,021 mm, mil 30,035–30,048 mm aralığında üretiliyor. Bu geçmenin türü nedir?', 'Sıkı geçme', ['Boşluklu geçme', 'Belirsiz geçme', 'Kayar geçme'], 'Milin en küçük ölçüsü (30,035) deliğin en büyük ölçüsünden (30,021) büyüktür; her durumda sıkılık oluşur.'),
  ('ISO geçme sisteminde \'H7\' gösteriminde büyük harf H neyi belirtir?', 'Deliğe ait tolerans konumunu', ['Mile ait tolerans konumunu', 'Yüzey pürüzlülüğünü', 'Malzemenin sertliğini'], 'ISO 286\'da büyük harfler delikleri, küçük harfler milleri gösterir; H konumunda deliğin alt sapması sıfırdır.'),
  ('Bir tasarımcı tüm ölçülere gereğinden çok dar tolerans veriyor. Bunun en olası sonucu nedir?', 'Maliyet ve ıskarta gereksiz artar', ['Parçalar birbirine hiçbir zaman uymaz ve montaj yapılamaz', 'Ürün kendiliğinden hafifler', 'Ölçüm yapmaya gerek kalmaz'], 'Dar tolerans daha hassas makine, daha çok kontrol ve daha fazla ret demektir; tolerans işlevin gerektirdiği kadar dar seçilmelidir.'),
  ('Uç uca eklenen üç parçanın her birinin toleransı ±0,1 mm\'dir. En kötü durum yaklaşımıyla toplam uzunluğun toleransı ne olur?', '±0,3 mm', ['±0,1 mm', '±0,17 mm', '±0,03 mm'], 'En kötü durum tolerans yığılmasında toleranslar doğrudan toplanır: 0,1 + 0,1 + 0,1 = 0,3 mm. İstatistiksel (karekök) yöntem yaklaşık ±0,17 mm verirdi.'),
  ('Geometrik toleranslandırmada \'düzlemsellik\' toleransı neyi sınırlar?', 'Yüzeyin ideal düzlemden sapmasını', ['Bir deliğin çapını', 'İki yüzey arasındaki açının 90 dereceden farkını', 'Parçanın kütlesini'], 'Düzlemsellik, yüzeyin tüm noktalarının birbirine paralel iki düzlem arasında kalmasını isteyen bir biçim toleransıdır.'),
  ('Sonlu elemanlar yönteminin (FEM) temel fikri nedir?', 'Cismi küçük elemanlara bölerek yaklaşık çözmek', ['Cismi tek bir eleman olarak kesin çözmek', 'Yalnız deneysel ölçümlerle sonuç almak', 'Malzeme özelliklerini hiç kullanmadan yalnız geometriden sonuç çıkarmak'], 'FEM, cismi ağ (mesh) ile küçük elemanlara ayırır ve her elemanın denklemlerini birleştirerek gerilme, sıcaklık gibi büyüklükleri sayısal olarak hesaplar.'),
  ('Simülasyon sonuçlarının güvenilir sayılabilmesi için yapılan \'doğrulama\' (validation) adımı hangisidir?', 'Sonuçları deney verileriyle karşılaştırmak', ['Ağ sayısını rastgele artırıp sonucun değişmesini beklemek', 'Renk skalasını değiştirmek', 'Sonuç dosyasını yedeklemek'], 'Validasyon modelin gerçeği ne kadar iyi temsil ettiğini sınar; bunun için bağımsız deneysel ölçümler kullanılır.'),
  ('Avrupa Ekonomik Alanı\'nda bir ürün üzerindeki CE işareti neyi ifade eder?', 'İlgili AB mevzuatına uygunluk beyanını', ['Ürünün Çin\'de üretildiğini', 'Ürünün piyasadaki en yüksek kaliteye sahip olduğunu', 'Ürünün çevre ödülü aldığını'], 'CE işareti bir kalite ödülü değil, uygunluk beyanıdır; üretici ürünün güvenlik, sağlık ve çevre gerekliliklerini karşıladığını beyan eder.'),
  ('Kritik yolda olmayan bir etkinliğin 4 günlük bolluğu vardır ve 3 gün gecikir. Proje bitiş tarihi bundan nasıl etkilenir?', 'Etkilenmez', ['3 gün gecikir', '4 gün gecikir', '1 gün öne çekilir'], 'Gecikme bolluktan küçük olduğu sürece proje bitişi değişmez; yalnız o etkinliğin bolluğu 1 güne iner.'),
  ('Değer mühendisliğinde \'değer\' genellikle hangi oranla ifade edilir?', 'İşlev / maliyet', ['Maliyet / kütle', 'Satış fiyatı / üretim adedi', 'Kâr / çalışan sayısı'], 'Değer mühendisliği, gerekli işlevi koruyarak ya da iyileştirerek maliyeti düşürmeyi, böylece işlev/maliyet oranını artırmayı amaçlar.'),
  ('\'Üretilebilirlik için tasarım\' (DFM) yaklaşımında aşağıdakilerden hangisi önerilir?', 'Parça sayısını azaltmak ve standart bileşen kullanmak', ['Her parçayı özel bir kalıpla ayrı ayrı üretmek', 'Montajda olabildiğince çok farklı vida tipi kullanmak', 'Toleransları işlevden bağımsız olarak en dar tutmak'], 'Daha az ve standart parça, montajı hızlandırır, stoku azaltır ve maliyeti düşürür.'),
  ('Türkiye\'de ve birçok ülkede patentin koruma süresi başvuru tarihinden itibaren genellikle kaç yıldır?', '20', ['10', '50', '70'], 'Patentler, TRIPS anlaşmasıyla uyumlu olarak başvurudan itibaren 20 yıl korunur; faydalı modelde bu süre Türkiye\'de 10 yıldır.'),
  ('Bir buluşun patentlenebilmesi için aranan üç temel koşul hangisidir?', 'Yenilik, buluş basamağı, sanayiye uygulanabilirlik', ['Estetik görünüm, yüksek fiyat ve pazar payı', 'Yerli üretim, düşük maliyet ve hızlı teslim', 'Uzun deneme süresi, ödül ve basında yer alma'], 'Buluş dünyada daha önce açıklanmamış olmalı, alanın uzmanı için apaçık olmamalı ve sanayide üretilebilmelidir.'),
  ('Bir ürünün yalnız dış görünüşünü (biçim, çizgi, renk düzeni) korumak isteyen üretici hangi tescili seçmelidir?', 'Tasarım tescili', ['Patent', 'Marka', 'Coğrafi işaret'], 'Endüstriyel tasarım tescili ürünün görünümünü korur; teknik işlev patentle, ayırt edici işaret markayla korunur.'),
  ('Çekmeye zorlanan bir çubuk eksen boyunca uzarken enine daralır. Enine şekil değiştirmenin boyuna şekil değiştirmeye oranının mutlak değerine ne ad verilir?', 'Poisson oranı', ['Elastisite modülü', 'Kayma modülü', 'Uzama yüzdesi'], 'Poisson oranı ν = −ε_enine / ε_boyuna\'dır; metallerde tipik olarak 0,3 civarındadır.'),
  ('Bir cıvata, birbirine göre kaymaya çalışan iki levhayı birleştiriyor. Cıvatanın kesitinde esas olarak hangi gerilme oluşur?', 'Kayma gerilmesi', ['Çekme gerilmesi', 'Basma gerilmesi', 'Isıl gerilme'], 'Levhalar kesit düzlemine paralel yönde kaymaya çalıştığından cıvata kesitinde kayma (makaslama) gerilmesi oluşur.'),
  ('Sünek bir metal çubukta çekme deneyinde en yüksek yükten sonra kesitin yerel olarak hızla daralmasına ne denir?', 'Boyun verme', ['Pekleşme', 'Sünme', 'Gevrek kırılma'], 'Boyun vermede şekil değiştirme dar bir bölgede yoğunlaşır; mühendislik gerilmesi düşer, kopma bu bölgede olur.'),
  ('Gerçek gerilme ile mühendislik gerilmesi arasındaki fark nereden kaynaklanır?', 'Gerçek gerilmenin anlık kesit alanıyla hesaplanmasından', ['Gerçek gerilmenin sıcaklıkla çarpılmasından', 'Mühendislik gerilmesinin kütleye bölünmesinden', 'Gerçek gerilmenin yalnız basmada tanımlanmasından'], 'Mühendislik gerilmesi ilk kesit alanını kullanır; gerçek gerilme ise o anki, daralmış alanı kullandığından boyun vermede daha yüksek çıkar.'),
  ('Charpy deneyinde çentikli bir numune neyle kırılır ve ne ölçülür?', 'Sarkaçla; kırılmada harcanan enerji', ['Hidrolik presle; numunenin akma dayanımı ve uzaması', 'Elmas uçla; batma izinin köşegen uzunluğu', 'Dönen kirişle; kırılmaya kadar geçen çevrim sayısı'], 'Charpy darbe deneyinde serbest bırakılan sarkacın kırılma sonrası daha az yükselmesinden numunenin soğurduğu enerji (joule) bulunur.'),
  ('Vickers sertlik deneyinin batıcı ucunun biçimi nedir?', 'Kare tabanlı elmas piramit', ['Çelik bilye', 'Yuvarlak uçlu kalem', 'Silindirik zımba'], 'Vickers deneyinde tepe açısı 136° olan kare tabanlı elmas piramit kullanılır; iz köşegenleri ölçülür.'),
  ('Rockwell deneyini Brinell ve Vickers\'tan ayıran temel özellik nedir?', 'Sertliği iz büyüklüğünden değil batma derinliğinden bulması', ['Hiç batıcı uç kullanmadan ses dalgasıyla ölçmesi', 'Yalnız ahşap ve plastikler için tasarlanmış olması', 'Ölçüm için numunenin kırılmasını gerektirmesi'], 'Rockwell\'de ön yük ve ana yük uygulanır, derinlik farkı doğrudan sertlik değerine çevrilir; bu yüzden hızlıdır.'),
  ('Bir mineral camı (yaklaşık 5,5) çiziyor ama kuvars (7) tarafından çiziliyor. Bu mineralin Mohs sertliği için en olası aralık hangisidir?', '5,5 ile 7 arası', ['1 ile 3 arası', '7 ile 10 arası', 'Tam olarak 5,5'], 'Camı çizdiği için ondan sert, kuvars tarafından çizildiği için kuvarstan yumuşaktır.'),
  ('Çeliklerde sertlik ile çekme dayanımı arasında nasıl bir ilişki gözlenir?', 'Kabaca doğru orantılı', ['Ters orantılı bir ilişki vardır, sert çelik zayıftır', 'Hiçbir ilişki yoktur, biri diğerini hiç göstermez', 'Yalnız sıcaklık 1000 °C\'yi aşınca ilişki ortaya çıkar'], 'Çeliklerde Brinell sertliğinden çekme dayanımı yaklaşık olarak tahmin edilebilir; bu yüzden sertlik ölçümü hızlı bir kalite kontrol aracıdır.'),
  ('Wöhler (S-N) eğrisi hangi iki büyüklük arasındaki ilişkiyi gösterir?', 'Gerilme genliği ile kırılmaya kadarki çevrim sayısı', ['Sıcaklık ile uzama hızı arasındaki ilişki', 'Sertlik ile batma derinliği arasındaki ilişki', 'Akım ile gerilim arasındaki ilişki'], 'S-N eğrisinde gerilme genliği azaldıkça parçanın dayanabildiği çevrim sayısı artar.'),
  ('Bazı çeliklerin S-N eğrisi belirli bir gerilmenin altında yataylaşır. Bu gerilme düzeyine ne denir?', 'Yorulma sınırı', ['Akma sınırı', 'Orantı sınırı', 'Kopma uzaması'], 'Yorulma (dayanım) sınırının altındaki gerilme genliklerinde çelik pratikte sonsuz çevrime dayanır; alüminyum alaşımlarında belirgin böyle bir sınır yoktur.'),
  ('Bir milde yorulma ömrünü artırmak için aşağıdakilerden hangisi en etkilidir?', 'Kesit geçişlerinde keskin köşe yerine yarıçap kullanmak', ['Yüzeyi bilerek pürüzlü bırakmak', 'Mile çentik açarak kütleyi azaltmak', 'Gerilme yığılmasını artıracak delik eklemek'], 'Yorulma çatlakları genellikle gerilme yığılması olan çentik ve köşelerde başlar; yuvarlatma ve düzgün yüzey ömrü uzatır.'),
  ('Kurşun boruların yıllar içinde kendi ağırlıklarıyla sarkması hangi olayla açıklanır?', 'Oda sıcaklığında sünme', ['Yorulma çatlağı', 'Galvanik korozyon', 'Isıl genleşme'], 'Kurşunun ergime sıcaklığı düşüktür (yaklaşık 600 K), bu yüzden oda sıcaklığı onun için yüksek homolog sıcaklıktır ve sünme görülür.'),
  ('Çelikte karbon oranı artırıldığında genellikle ne olur?', 'Sertlik ve dayanım artar, süneklik azalır', ['Sertlik azalır, süneklik çok artar', 'Hiçbir mekanik özellik değişmez', 'Yoğunluk iki katına çıkar'], 'Karbon, sementit oluşturarak ve martensiti sertleştirerek dayanımı artırır, ancak kaynak edilebilirliği ve sünekliği düşürür.'),
  ('Perlit yapısı hangi iki fazın ince katmanlarından oluşur?', 'Ferrit ve sementit', ['Östenit ve martensit', 'Grafit ve cam', 'Bakır ve çinko'], 'Perlit, ferrit (α-demir) ile sementitin (Fe₃C) ardışık ince lamellerinden oluşan ötektoid yapıdır.'),
  ('Kaynaklı çelik bir köprü kirişi için yapı çeliği seçilirken düşük karbonlu çeliğin tercih edilmesinin başlıca nedeni nedir?', 'Kaynak edilebilirliğinin iyi olması', ['Kesinlikle hiç paslanmaması', 'Elmastan sert olması', 'Elektriği iletmemesi'], 'Yüksek karbon kaynak bölgesinde sert ve gevrek yapı ile çatlama riski yaratır; düşük karbonlu çelikler kolay kaynaklanır.'),
  ('Yüksek fırından çıkan, yüksek karbonlu ve gevrek ilk ürüne ne ad verilir?', 'Pik demir', ['Paslanmaz çelik', 'Dövme demir', 'Takım çeliği'], 'Pik demir yaklaşık %4 karbon içerir; çelik üretmek için bazik oksijen fırınında karbonu düşürülür.'),
  ('Su verilmiş çeliğin daha düşük bir sıcaklığa yeniden ısıtılıp tutulmasının (temperleme) amacı nedir?', 'Gevrekliği azaltıp tokluğu artırmak', ['Sertliği en üst düzeye çıkarmak ve sünekliği sıfırlamak', 'Çeliğin karbon oranını iki katına çıkarmak', 'Yüzeyi parlatmak ve rengini değiştirmek'], 'Temperleme martensitteki iç gerilmeleri giderir; biraz sertlik kaybı karşılığında tokluk önemli ölçüde artar.'),
  ('Bir dişli yüzeyinin aşınmaya dayanıklı sert, iç kısmının ise tok kalması isteniyor. Hangi işlem en uygundur?', 'Sementasyon ve ardından su verme', ['Tüm parçanın tavlanarak yumuşatılması', 'Parçanın yalnız boyanması', 'Parçanın sıvı azotta saklanması'], 'Sementasyonda yüzeye karbon yayındırılır; su vermede yalnız karbonca zengin yüzey çok sertleşir, düşük karbonlu çekirdek tok kalır.'),
  ('Talaşlı işlenmesi zor, sert bir çelik çubuğu yumuşatmak için hangi ısıl işlem uygulanır?', 'Tam tavlama', ['Su verme', 'Bilyeli dövme', 'Anodik oksitleme'], 'Tam tavlamada çelik östenit bölgesine ısıtılıp fırında yavaş soğutulur; yumuşak ve kolay işlenen kaba perlit oluşur.'),
  ('Normalizasyonu tam tavlamadan ayıran fark nedir?', 'Soğutmanın fırında değil havada yapılması', ['Isıtmanın hiç yapılmaması ve oda sıcaklığında beklenmesi', 'Parçanın suya daldırılarak hızla soğutulması', 'Isıtmanın yalnız yüzeyde lazer ile yapılması'], 'Normalizasyonda havada soğuma tavlamaya göre biraz daha hızlıdır; daha ince ve düzgün tane yapısı elde edilir.'),
  ('Titanyum alaşımlarının biyomedikal implantlarda tercih edilmesinin başlıca nedeni nedir?', 'Vücutla uyumlu ve korozyona dayanıklı olması', ['Çok ucuz ve kolay işlenmesi', 'Manyetik alanla güçlü biçimde çekilmesi', 'Elektriği çok iyi iletmesi'], 'Titanyum yüzeyinde kararlı bir oksit tabakası oluşur; bu sayede vücut sıvılarında korozyona uğramaz ve doku ile uyumludur.'),
  ('Ampullerin ve TIG kaynak elektrotlarının telinde tungsten kullanılmasının temel nedeni nedir?', 'Metaller arasında en yüksek ergime sıcaklığına sahip olması', ['En hafif metal olması', 'Oda sıcaklığında sıvı olması', 'Hiç ısı iletmemesi'], 'Tungsten yaklaşık 3422 °C\'de erir; bu yüzden çok yüksek sıcaklıkta katı kalabilir.'),
  ('Ticari olarak kullanılan yapısal metaller arasında en düşük yoğunluğa sahip olanı hangisidir?', 'Magnezyum', ['Alüminyum', 'Titanyum', 'Çinko'], 'Magnezyumun yoğunluğu yaklaşık 1,74 g/cm³\'tür; alüminyumdan (2,7) ve titanyumdan (4,5) hafiftir.'),
  ('Lehim alaşımlarında geleneksel olarak kurşunla birlikte kullanılan, günümüz kurşunsuz lehimlerinin de ana bileşeni olan metal hangisidir?', 'Kalay', ['Demir', 'Krom', 'Platin'], 'Kalay-kurşun lehimleri düşük ergime sıcaklığıyla yaygındı; kurşunsuz lehimler ise kalayı gümüş ve bakırla alaşımlar.'),
  ('Nikel esaslı süper alaşımlar en çok hangi kullanım alanıyla öne çıkar?', 'Jet motorlarının sıcak bölge türbin kanatları', ['Gıda ambalajı folyoları', 'Elektrik prizlerinin plastik gövdeleri', 'Ahşap mobilya bağlantı çivileri'], 'Süper alaşımlar çok yüksek sıcaklıklarda sünmeye ve oksitlenmeye dayanıklıdır; bu yüzden gaz türbinlerinde kullanılır.'),
  ('Oda sıcaklığında demirin (α-demir) kristal yapısı hangisidir?', 'Hacim merkezli kübik', ['Yüzey merkezli kübik', 'Sıkı paket altıgen', 'Amorf'], 'α-demir (ferrit) HMK yapıdadır; yaklaşık 912 °C\'nin üzerinde YMK yapılı γ-demire (östenit) dönüşür.'),
  ('Bir metalin tane boyutu küçültüldüğünde akma dayanımı genellikle nasıl değişir?', 'Artar', ['Azalır', 'Değişmez', 'Önce sıfıra iner'], 'Hall-Petch ilişkisine göre tane sınırları dislokasyon hareketini engeller; daha çok sınır, daha yüksek dayanım demektir.'),
  ('Kristal kafeste bir atomun bulunması gereken yerin boş kalmasına ne ad verilir?', 'Boşluk kusuru', ['Tane sınırı', 'Kenar dislokasyonu', 'İkiz sınırı'], 'Boşluk (vakans) noktasal bir kusurdur; atomların yayınması (difüzyon) büyük ölçüde boşluklar üzerinden gerçekleşir.'),
  ('Metallerin plastik şekil değiştirmesi mikroskobik düzeyde esas olarak hangi mekanizmayla gerçekleşir?', 'Dislokasyonların hareketiyle', ['Atomların çekirdeklerinin bölünmesiyle', 'Elektronların kristali terk etmesiyle', 'Moleküllerin buharlaşmasıyla'], 'Dislokasyonlar kayma düzlemlerinde ilerleyerek atom düzlemlerinin aşamalı olarak birbirine göre kaymasını sağlar.'),
  ('Çelik bir cıvata bakır bir levhaya tuzlu su ortamında temas ediyor. Hangisinin hızlı korozyona uğraması beklenir?', 'Çelik cıvata', ['Bakır levha', 'İkisi de eşit hızla', 'Korozyon olmaz, çünkü tuzlu su yüzeyi korur'], 'Galvanik çiftte daha aktif (daha az soy) metal anot olur ve çözünür; demir bakıra göre daha aktiftir.'),
  ('Gemi gövdelerine ve yer altı boru hatlarına magnezyum ya da çinko bloklar bağlanmasının amacı nedir?', 'Bu blokların kurban anot olarak çözünüp çeliği korumasını sağlamak', ['Gövdenin ağırlık merkezini dengelemek ve yalpayı azaltmak', 'Suyun sürtünmesini azaltıp gemiyi hızlandırmak', 'Çeliğin elektriği daha iyi iletmesini sağlamak'], 'Katodik korumada daha aktif metal anot olur; çelik katot konumuna geçtiği için korozyona uğramaz.'),
  ('Alüminyumun havada demir gibi hızla \'paslanmamasının\' nedeni nedir?', 'Yüzeyinde ince ve koruyucu oksit tabakası oluşması', ['Alüminyumun oksijenle hiç tepkimeye girmemesi', 'Alüminyumun soy metal olması', 'Havadaki azotun alüminyumu kaplaması'], 'Alüminyum aslında aktif bir metaldir; oluşan yoğun Al₂O₃ tabakası alttaki metali korur. Anodik oksitleme bu tabakayı kalınlaştırır.'),
  ('Termoset polimerlerin ısıtıldığında yeniden şekillendirilememesinin nedeni nedir?', 'Zincirler arasında kalıcı çapraz bağlar bulunması', ['Zincirlerinin çok kısa olması', 'Hiç karbon içermemeleri', 'Kristal yapılarının metalik olması'], 'Kürlenme sırasında oluşan üç boyutlu çapraz bağ ağı ısıtıldığında çözülmez; malzeme yumuşamak yerine bozunur.'),
  ('Aşağıdaki ürünlerden hangisi tipik olarak termoset bir polimerden yapılır?', 'Epoksi yapıştırıcı', ['PET su şişesi', 'Polietilen poşet', 'Naylon misina'], 'Epoksi reçine sertleştiriciyle tepkimeye girerek çapraz bağlanır; PET, polietilen ve naylon termoplastiktir.'),
  ('Doğal kauçuğun kükürtle ısıtılarak dayanıklı ve esnek hâle getirilmesine ne ad verilir?', 'Vulkanizasyon', ['Galvanizleme', 'Polimerizasyon kırılması', 'Sementasyon'], 'Charles Goodyear\'ın geliştirdiği vulkanizasyonda kükürt, kauçuk zincirleri arasında çapraz bağlar oluşturur.'),
  ('Camsı geçiş sıcaklığı (Tg) bir polimer için ne ifade eder?', 'Amorf bölgelerin sert-camsı hâlden yumuşak-lastiksi hâle geçtiği sıcaklık', ['Polimerin tamamen buharlaştığı sıcaklık', 'Polimerin kristallerinin oluştuğu tek sıcaklık', 'Polimerin elektriği iletmeye başladığı sıcaklık'], 'Tg\'nin altında zincir hareketi donmuştur ve malzeme gevrektir; üstünde zincir segmentleri hareket eder ve malzeme esnekleşir.'),
  ('Temperli (sertleştirilmiş) camın kırıldığında küçük, köşesiz parçalara ayrılmasının nedeni nedir?', 'Yüzeydeki basma, içteki çekme artık gerilmeleri', ['Camın içine çelik tel örgüsü konması', 'Camın plastik katmanla kaplanması', 'Camın daha yumuşak bir bileşime sahip olması'], 'Hızlı hava soğutmasıyla yüzey basma altında kalır; kırılma başlayınca depolanmış enerji camı küçük taneciklere böler.'),
  ('Otomobil ön camlarında kırıldığında parçaların dağılmamasını sağlayan çözüm hangisidir?', 'İki cam arasına polimer ara katman koyarak lamine etmek', ['Camı yalnız daha kalın dökmek', 'Camın yüzeyini zımparalayarak pürüzlendirmek', 'Cama yüksek oranda kurşun eklemek'], 'Lamine camda PVB katmanı kırılan parçaları tutar; yolcuların cam parçalarından yaralanma riski azalır.'),
  ('Borosilikat camın (laboratuvar ve fırın kapları) sıradan cama göre ısıl şoka dayanıklı olmasının nedeni nedir?', 'Isıl genleşme katsayısının çok düşük olması', ['Elektriği çok iyi iletmesi', 'Erime sıcaklığının oda sıcaklığına yakın olması', 'Hiç silisyum içermemesi'], 'Bor oksit katkısı genleşme katsayısını düşürür; ani sıcaklık farkında oluşan ısıl gerilmeler küçük kalır.'),
  ('Karbon fiber takviyeli polimerlerin yarış bisikletlerinde ve uçaklarda kullanılmasının başlıca nedeni nedir?', 'Yüksek özgül dayanım ve rijitlik', ['Çok düşük üretim maliyeti', 'Kolay geri dönüştürülebilmesi', 'Darbeye karşı sınırsız dayanımı'], 'Karbon lifler hafif ve çok rijittir; ağırlık başına dayanım ve rijitlikte çoğu metali geçer, ancak pahalıdır ve geri dönüşümü zordur.'),
  ('Tek yönlü lif takviyeli bir kompozit levhanın özellikleri için hangi ifade doğrudur?', 'Lif yönünde dayanımı yüksek, lif yönüne dik doğrultuda düşüktür', ['Her yönde aynı dayanım gösterir', 'Lif yönüne dik doğrultuda daha dayanıklıdır', 'Lif yönü dayanımı hiç etkilemez'], 'Bu tür kompozitler anizotroptur; bu yüzden katmanlar farklı açılarla yerleştirilerek yük doğrultularına uygun dayanım sağlanır.'),
  ('Lif ve matris oranları bilinen bir kompozitin lif doğrultusundaki elastisite modülü \'karışım kuralı\' ile tahmin ediliyor. Lif E=230 GPa, matris E=3 GPa ve lif hacim oranı 0,6 ise kompozitin modülü yaklaşık kaçtır?', '139,2 GPa', ['116,5 GPa', '233 GPa', '69,0 GPa'], 'E = 0,6 × 230 + 0,4 × 3 = 138 + 1,2 = 139,2 GPa bulunur.'),
  ('Kerpiçteki saman ile cam elyaf takviyeli polyesterdeki cam lifler arasındaki ortak işlev nedir?', 'İkisi de matrisi güçlendiren takviye bileşenidir', ['İkisi de malzemeye renk veren pigmenttir', 'İkisi de malzemeyi suya dayanıksız kılar', 'İkisi de yalnız ağırlık artırmak için konur'], 'Kerpiç tarihî bir kompozit örneğidir: saman lifleri çamur matrisindeki çatlamayı sınırlar, cam lif de reçineyi güçlendirir.'),
  ('Ahşabın lif yönünde ve life dik yönde farklı dayanım göstermesi hangi kavramla açıklanır?', 'Anizotropi', ['İzotropi', 'Süperiletkenlik', 'Pasifleşme'], 'Ahşap doğal bir kompozittir; selüloz lifleri yönlendiği için özellikleri yöne bağlıdır.'),
  ('Bimetal termostat şeridinin ısınınca bükülmesi hangi ilkeye dayanır?', 'Farklı genleşme katsayıları', ['Metallerin ısınınca mıknatıslanması', 'Isının metali eritip akıtması', 'Şeridin sıcakta elektrik üretmesi'], 'Birbirine yapıştırılmış iki metalden biri daha çok uzar; şerit daha az genleşen metal tarafına doğru bükülür ve kontağı açıp kapatır.'),
  ('Bir metalin elektriksel özdirenci sıcaklık arttıkça genellikle nasıl değişir?', 'Artar', ['Azalır', 'Değişmez', 'Sıfıra iner'], 'Sıcaklıkla kafes titreşimleri artar ve elektronların saçılması çoğalır; bu yüzden metallerin direnci yükselir. Yarı iletkenlerde ise tersi görülür.'),
  ('Özgül ısısı yüksek bir malzeme için hangi ifade doğrudur?', 'Aynı ısı ile sıcaklığı az artar', ['Isıyı hiç iletmez ve tümüyle yansıtır', 'Sıcaklığı çok hızlı yükselir', 'Yoğunluğu her zaman çok düşüktür'], 'Özgül ısı, birim kütlenin sıcaklığını 1 derece artırmak için gereken ısıdır; su bu nedenle iyi bir ısı depolama ortamıdır.'),
  ('Yalıtım köpüklerinin ısıyı az iletmesinin temel nedeni nedir?', 'İçlerindeki küçük hava hücreleri', ['Malzemenin metal tozu içermesi', 'Köpüğün ısıyı elektriğe dönüştürmesi', 'Hücrelerin tamamen suyla dolu olması'], 'Hareketsiz hapsedilmiş gaz çok kötü bir ısı iletkenidir; küçük hücreler taşınımla ısı aktarımını da engeller.'),
  ('Çekme dayanımı 500 MPa, yoğunluğu 7,8 g/cm³ olan çelik ile çekme dayanımı 300 MPa, yoğunluğu 2,7 g/cm³ olan alüminyum alaşımı karşılaştırılıyor. Özgül dayanım için hangi sonuç doğrudur?', 'Alüminyum alaşımınki daha yüksektir', ['Çeliğinki yaklaşık iki kat daha yüksektir', 'İkisinin özgül dayanımı tam olarak eşittir', 'Özgül dayanım bu verilerle hesaplanamaz'], 'Çelik: 500/7,8 ≈ 64; alüminyum: 300/2,7 ≈ 111. Alüminyumun birim yoğunluk başına dayanımı daha yüksektir.'),
  ('Bir firma, bir parçanın malzemesini değiştirmeden önce \'tüm yaşam boyu maliyet\' hesaplıyor. Bu hesaba hangisi girmez?', 'Rakip firmanın kârı', ['Satın alma ve üretim maliyeti', 'Bakım ve onarım giderleri', 'Ömür sonu bertaraf maliyeti'], 'Yaşam boyu maliyet, ürünün kendi ömrü boyunca katlanılan giderleri kapsar; başka bir firmanın kârı bu hesabın parçası değildir.'),
  ('Bir elektronik kartın soğutucusu için alüminyumun bakıra tercih edilmesinin en makul gerekçesi hangisidir?', 'Daha hafif ve ucuz olması', ['Isıl iletkenliğinin bakırdan yüksek olması', 'Elektriği hiç iletmemesi', 'Ergime sıcaklığının bakırdan yüksek olması'], 'Bakır ısıyı daha iyi iletir ama daha ağır ve pahalıdır; çoğu uygulamada alüminyumun yeterli iletkenliği ve hafifliği tercih sebebidir.'),
  ('Yüzeye açılan ince çatlakları bulmak için parçaya renkli sıvı sürülüp silindikten sonra geliştirici uygulanan yöntem hangisidir?', 'Sıvı penetrant muayenesi', ['Ultrasonik muayene', 'Radyografik muayene', 'Girdap akımı muayenesi'], 'Penetrant kılcallıkla çatlağa girer; geliştirici onu geri çekerek çatlağı görünür kılar. Yöntem yalnız yüzeye açık kusurları gösterir.'),
  ('Manyetik parçacık muayenesi hangi malzemelerde kullanılabilir?', 'Ferromanyetik malzemelerde', ['Yalnız camda', 'Alüminyum ve bakırda', 'Plastik ve ahşapta'], 'Yöntem, kusurun yarattığı manyetik kaçak alanda demir tozlarının toplanmasına dayanır; bu yüzden çelik gibi ferromanyetik malzemeler gerekir.'),
  ('Metrenin günümüzdeki tanımı hangi büyüklüğe dayanır?', 'Işığın boşlukta belirli bir sürede aldığı yol', ['Paris\'teki platin çubuğun uzunluğu', 'Ekvator ile kutup arası mesafenin onda biri', 'Bir sarkacın bir saniyedeki salınım boyu'], '1983\'ten beri metre, ışığın boşlukta 1/299 792 458 saniyede aldığı yol olarak tanımlanır.'),
  ('Aşağıdaki gösterimlerden hangisi SI yazım kurallarına uygundur?', '5 kg', ['5 kilo', '5 kgs', '5 kg.'], 'Birim simgeleri çoğul eki almaz, sonuna nokta konmaz; kilogram için kısaltılmış "kilo" değil, kg simgesi kullanılır.'),
  ('İki ölçüm arasındaki 10 °C\'lik sıcaklık farkı kaç kelvinlik farka karşılık gelir?', '10', ['283,15', '263,15', '50'], 'Celsius ve kelvin ölçeklerinin bir derecelik aralığı eşittir; yalnız sıfır noktaları farklıdır. Bu yüzden farklar aynıdır.'),
  ('1999\'da NASA\'nın Mars Climate Orbiter sondasının kaybedilmesine yol açan temel hata neydi?', 'İki ekibin farklı birim sistemleri kullanması', ['Sondanın güneş panellerinin hiç açılmaması', 'Fırlatma aracının kalkışta patlaması', 'Sondanın yazılımının bir virüs tarafından silinmesi'], 'Bir yazılım itki verisini pound-kuvvet·saniye, diğeri newton·saniye olarak işledi; sonda Mars atmosferine çok yakın geçerek kayboldu.'),
  ('Boyut analizi açısından hangi denklem kesinlikle yanlıştır? (v hız, a ivme, t zaman, x yol)', 'x = v·t²', ['x = v·t', 'v = a·t', 'x = a·t²/2'], 'v·t² ifadesinin boyutu (m/s)·s² = m·s\'dir; yolun boyutu m olduğu için denklem tutarsızdır.'),
  ('Bir terazi aynı 100 g\'lık kütleyi beş kez 102,1; 102,0; 102,1; 102,2; 102,0 g ölçüyor. Bu terazi için hangi değerlendirme doğrudur?', 'Kesin ama doğru değil', ['Doğru ama kesin değil', 'Hem doğru hem kesin', 'Ne doğru ne kesin'], 'Ölçümler birbirine çok yakın (kesin) ama gerçek değerden yaklaşık 2 g sapmış (doğru değil); bu sistematik hataya işaret eder.'),
  ('Hedef tahtası benzetmesinde atışlar hedefin merkezinin etrafına geniş biçimde dağılmış, ortalamaları ise merkeze denk geliyor. Bu durum neyi temsil eder?', 'Doğru ama kesin olmayan ölçümleri', ['Kesin ama doğru olmayan ölçümleri', 'Hem doğru hem kesin ölçümleri', 'Kaba hatayla bozulmuş tek bir ölçümü'], 'Ortalama gerçek değere yakın olduğu için doğruluk iyi, dağılım geniş olduğu için kesinlik düşüktür.'),
  ('Sistematik hata için hangi ifade doğrudur?', 'Ölçümleri hep aynı yönde kaydırır', ['Ölçüm sayısı artırılınca kendiliğinden yok olur', 'Tamamen rastgele işaretlerde ortaya çıkar', 'Yalnız okuyan kişinin dikkatsizliğinden doğar'], 'Sistematik hata sıfır ayarı kaymış bir alet gibi nedenlerle ölçümleri tek yöne iter; ortalama almak onu gidermez, kalibrasyon gerekir.'),
  ('0,004050 sayısında kaç anlamlı basamak vardır?', '4', ['7', '3', '6'], 'Baştaki sıfırlar anlamlı değildir; 4, 0, 5 ve sondaki sıfır anlamlıdır. Toplam 4 anlamlı basamak bulunur.'),
  ('4,0 m ile 2,25 m\'nin çarpımı anlamlı basamak kurallarına göre nasıl ifade edilir?', '9,0 m²', ['9 m²', '9,00 m²', '9,000 m²'], 'Çarpmada sonuç en az anlamlı basamaklı veri kadar basamak taşır: 4,0 iki anlamlı basamaklıdır, bu yüzden 9,0 m² yazılır.'),
  ('Bağımsız iki uzunluk ölçümü 10,0 ± 0,3 cm ve 5,0 ± 0,4 cm\'dir. Toplamın belirsizliği karelerin toplamının karekökü yöntemiyle kaç cm\'dir?', '0,5', ['0,7', '0,1', '0,35'], 'Bağımsız belirsizlikler toplamda karesel eklenir: √(0,3² + 0,4²) = √0,25 = 0,5 cm.'),
  ('Dijital bir multimetrenin ekranında son basamağın değişmesiyle oluşan en küçük fark neyi gösterir?', 'Çözünürlüğü', ['Kalibrasyon tarihini', 'Pil ömrünü', 'Doğruluğunu kesin olarak'], 'Çözünürlük aletin ayırt edebildiği en küçük değişimdir; çözünürlüğün yüksek olması doğruluğun da yüksek olduğu anlamına gelmez.'),
  ('Bir ölçü aleti 0,01 mm çözünürlüğe sahip ama kalibrasyonu yapılmamış. Bu alet için hangi yargı en sağlıklıdır?', 'Çok basamak göstermesi sonuçların doğru olduğunu garanti etmez', ['Çözünürlüğü yüksek olduğu için sonuçlar mutlaka doğrudur', 'Kalibrasyon yalnız mekanik aletlerde gerekir', 'Çözünürlük ile doğruluk aynı kavramdır'], 'Kalibrasyonsuz alet sistematik hata taşıyabilir; ince bölme ya da çok basamak doğruluk kanıtı değildir.'),
  ('Ölçmede \'izlenebilirlik\' kavramı neyi gerektirir?', 'Kesintisiz kalibrasyon zinciriyle ulusal ya da uluslararası standarda bağlanmayı', ['Ölçüm sonuçlarının internette paylaşılmasını', 'Her ölçümün aynı kişi tarafından yapılmasını', 'Ölçü aletinin seri numarasının görünür olmasını'], 'İzlenebilirlik, her basamağın belirsizliği bilinen kalibrasyonlarla sonucun SI tanımlarına kadar bağlanmasıdır.'),
  ('0,02 mm hassasiyetli bir kumpasta ana cetvelde verniyenin sıfırı 23 mm\'yi geçmiş, verniyenin 17. çizgisi ana cetveldeki bir çizgiyle çakışıyor. Okunan değer kaç milimetredir?', '23,34', ['23,17', '24,7', '23,85'], 'Ölçü = 23 + 17 × 0,02 = 23 + 0,34 = 23,34 mm.'),
  ('Mikrometrelerin cırcır (ratchet) düzeneğinin işlevi nedir?', 'Ölçüm baskısını her seferinde sabit tutmak', ['Tamburu hızla döndürüp ölçümü kısaltmak', 'Mikrometreyi kilitleyip taşımayı kolaylaştırmak', 'Ölçüm değerini dijital ekrana göndermek'], 'Fazla sıkmak parçayı ve vidayı esnetir; cırcır belirli kuvvette kaydırarak tekrarlanabilir temas sağlar.'),
  ('Bir teknisyen mikrometreyi kapattığında sıfır yerine +0,02 mm okuyor. Bir parçayı 12,46 mm okursa doğru değer nedir?', '12,44 mm', ['12,48 mm', '12,46 mm', '12,02 mm'], 'Alet kapalıyken 0,02 fazla gösteriyorsa bu sıfır hatası her okumadan çıkarılır: 12,46 − 0,02 = 12,44 mm.'),
  ('Komparatör (mihengir saati) genellikle ne amaçla kullanılır?', 'Küçük konum farklarını ve salgıyı ölçmek', ['Parçanın kütlesini tartmak', 'Elektrik akımını ölçmek', 'Parçanın rengini belirlemek'], 'Komparatör, ucunun küçük yer değiştirmelerini kadranda büyütür; torna aynasında milin salgısını görmek için sıkça kullanılır.'),
  ('Mastarla kontrolün sürmeli kumpasla ölçmeye göre üstünlüğü nedir?', 'Sayı okumadan hızlı kabul-ret kararı vermesi', ['Parçanın gerçek ölçüsünü sayı olarak vermesi', 'Her ölçüyü aynı aletle ölçebilmesi', 'Kalibrasyon gerektirmemesi'], 'Mastar yalnız sınır kontrolü yapar ama çok hızlıdır ve okuma hatasını ortadan kaldırır; ölçü değeri vermez.'),
  ('Bir vida dişinin adımını hızla belirlemek için kullanılan, farklı adımlarda dişli bıçaklardan oluşan alet hangisidir?', 'Vida tarağı', ['Sentil', 'Su terazisi', 'Pergel'], 'Vida tarağındaki bıçaklar dişe tek tek oturtulur; boşluksuz oturan bıçak adımı gösterir.'),
  ('İki yüzey arasındaki küçük aralığı ölçmek için kullanılan, kalınlığı belli ince çelik yapraklardan oluşan alet hangisidir?', 'Sentil', ['Kumpas', 'Vida tarağı', 'Komparatör ayağı'], 'Sentil (aralık mastarı) yaprakları sırayla aralığa sokulur; hafif sürtünmeyle geçen yaprağın kalınlığı aralığı verir.'),
  ('Dirençli sıcaklık algılayıcılarında (RTD) en yaygın kullanılan metal hangisidir?', 'Platin', ['Kurşun', 'Çinko', 'Magnezyum'], 'Platin geniş aralıkta kararlı ve doğrusala yakın direnç-sıcaklık ilişkisi gösterir; Pt100 0 °C\'de 100 ohm dirençlidir.'),
  ('Gerinim ölçerin direnç değişimleri çok küçük olduğundan genellikle hangi devreyle ölçülür?', 'Wheatstone köprüsü', ['Basit seri lamba devresi', 'Doğrultucu köprü diyot devresi', 'Yükseltici olmayan anten devresi'], 'Wheatstone köprüsü küçük direnç değişimlerini dengesizlik gerilimine çevirir; yarım ve tam köprü düzenleri sıcaklık etkisini de dengeleyebilir.'),
  ('Yüzey pürüzlülüğünü ifade etmek için en yaygın kullanılan parametre olan Ra neyi gösterir?', 'Ortalama sapma', ['Parçanın toplam kütlesi', 'Yüzeyin rengi ve parlaklığı', 'Malzemenin sertlik değeri ve ısıl işlem durumu'], 'Ra, profil çizgisinin ortalama çizgiden sapmalarının mutlak değerlerinin aritmetik ortalamasıdır; genellikle mikrometre cinsinden verilir.'),
  ('Bir yatak yüzeyi için Ra 0,4 µm, bir döküm gövde dış yüzeyi için Ra 12,5 µm isteniyor. Bu farkın en makul nedeni hangisidir?', 'Kayan yüzeyde sürtünme ve aşınma önemlidir', ['Döküm yüzeyi daha pahalı işlemle üretilmek istenir', 'Yatak yüzeyinin boyanması gerekir', 'Pürüzlülük yalnız görünüm için belirlenir'], 'İşlevsel temas yüzeyleri ince işlem gerektirir; işlevsiz dış yüzeyde pahalı ince işleme gereksizdir.'),
  ('Uluslararası standartlara göre boyut ölçümlerinde referans sıcaklık kaç °C\'dir?', '20', ['0', '25', '4'], 'ISO 1 standardı geometrik ürün özellikleri için referans sıcaklığı 20 °C olarak belirler.'),
  ('Hassas bir çelik parça elle uzun süre tutulduktan hemen sonra mikrometreyle ölçülürse ne olması beklenir?', 'Ölçü gerçeğinden biraz büyük çıkar', ['Ölçü gerçeğinden çok küçük çıkar', 'Parçanın kütlesi azalır', 'Mikrometre manyetik hâle gelir'], 'El sıcaklığı parçayı ısıtıp genleştirir; bu nedenle hassas ölçümde parça ve alet ortam sıcaklığına dengelenir, eldiven ya da yalıtımlı sap kullanılır.'),
  ('Yüzey pürüzlülüğü ölçen profilometrenin çalışma biçimi hangisidir?', 'Yüzeyde ince uçla ilerleyip iniş çıkışları kaydeder', ['Yüzeye bilye bastırıp iz çapını ölçer', 'Parçayı tartıp yoğunluğunu bulur', 'Yüzeye penetrant sürüp çatlakları gösterir'], 'Temaslı profilometrede elmas uçlu iğne yüzey boyunca sürüklenir ve dikey hareketleri elektriksel sinyale çevrilir.'),
  ('Kanada\'da mühendislik mezunlarının serçe parmaklarına taktığı demir yüzük geleneği neyi simgeler?', 'Mesleki sorumluluğu ve alçakgönüllülüğü', ['Mezuniyet derecesini ve not ortalamasını', 'Evliliği ve aileyi', 'Bir spor kulübüne üyeliği'], 'Yüzük töreni 1920\'lerde başladı; 1907 Quebec Köprüsü çöküşüyle ilişkilendirilen gelenek, mühendisin hatalarının bedelini hatırlatır.'),
  ('Bir mühendis, eşinin ortağı olduğu firmanın da katıldığı bir ihalede değerlendirme komisyonuna atanıyor. En uygun davranış hangisidir?', 'Durumu açıklayıp değerlendirmeden çekilmek', ['Kimseye söylemeden tarafsız olmaya çalışmak', 'Eşinin firmasına daha düşük puan vermek', 'İhaleyi iptal ettirmek için dilekçe yazmak'], 'Çıkar çatışmasında temel kural, durumu ilgililere açıklamak ve karar sürecinden çekilmektir; gizlemek güveni zedeler.'),
  ('Bir mühendis eski işvereninden ayrıldıktan sonra oradaki gizli üretim formülünü yeni işyerinde kullanıyor. Bu davranış öncelikle hangi yükümlülüğü ihlal eder?', 'Gizlilik', ['Kamu güvenliği', 'Yetkinlik', 'Sürekli eğitim'], 'Ticari sırlar işten ayrıldıktan sonra da korunur; bu bilgiyi kullanmak hem etik hem hukuki bir ihlaldir.'),
  ('Bir mühendis kendi hazırlamadığı ve denetlemediği bir projeyi imzalaması için para teklif alıyor. Bu teklifi kabul etmek neden etik dışıdır?', 'İmza, mühendisin işi denetleyip sorumluluk aldığını beyan eder', ['İmza atmak mühendisin elini yorar', 'Yalnız mühendisin vergisini artırır', 'Projenin rengi değişebilir'], 'Mühendis imzası, işin yetkin biçimde incelenip onaylandığı güvencesidir; denetlenmemiş işi imzalamak kamuyu yanıltır.'),
  ('Bir mühendis müşterinin isteği üzerine projesinde yapılan bir değişikliğin yangın yönetmeliğine aykırı olduğunu fark ediyor. İlk yapması gereken nedir?', 'Müşteriyi yazılı olarak uyarıp gerekçesini açıklamak', ['Değişikliği sessizce uygulamak', 'Projeyi bırakıp kimseye haber vermemek', 'Değişikliği basına duyurmak'], 'Önce sorunu doğrudan ilgili tarafa bildirmek ve kayıt altına almak gerekir; aykırılık sürerse yetkili makamlara başvurmak gündeme gelir.'),
  ('Bir projede birçok kişi küçük katkılar yaptığı için hatanın sorumlusunun bulunamaması etik literatürde nasıl adlandırılır?', 'Çok eller sorunu', ['Kartopu etkisi', 'Hale etkisi', 'Placebo etkisi'], '\'Problem of many hands\' kavramı, karmaşık örgütlerde sorumluluğun dağılarak kimsenin hesap vermemesi tehlikesini anlatır.'),
  ('Bir mühendisin \'Bana söyleneni yaptım, sorumluluk yöneticimde\' demesi hangi etik sorunu yansıtır?', 'Kişisel mesleki sorumluluğun reddi', ['Fikri mülkiyet hakkının korunması', 'Çevre bilincinin gelişmesi', 'Yetkinlik sınırının doğru bilinmesi'], 'Meslek etiği emir altında bile mühendisin kendi uzman yargısını kullanmasını ve kamuyu tehlikeye sokan işlere karşı çıkmasını ister.'),
  ('Challenger fırlatılmadan önceki gece contaları üreten firmanın mühendisleri ne önermişti?', 'Soğuk nedeniyle fırlatmanın ertelenmesini', ['Fırlatmanın bir gün öne alınmasını', 'Mekiğe ek yakıt konmasını', 'Mürettebat sayısının artırılmasını'], 'Roger Boisjoly gibi Morton Thiokol mühendisleri düşük sıcaklıkta O-halkalarına güvenilemeyeceğini söyledi; yönetim baskısıyla öneri geri çekildi.'),
  ('Challenger\'ı soruşturan Rogers Komisyonu\'nda buzlu suya batırılan conta malzemesiyle soğuğun etkisini gösteren fizikçi kimdir?', 'Richard Feynman', ['Albert Einstein', 'Carl Sagan', 'Enrico Fermi'], 'Feynman, kamuoyu önünde bir parça contayı buzlu suda sıkıştırarak esnekliğini yitirdiğini gösterdi.'),
  ('1985–1987 yılları arasında bazı hastalara aşırı ışın dozu verilmesine yol açan Therac-25 vakasının temel dersi nedir?', 'Güvenlik için yalnız yazılıma güvenmek tehlikelidir', ['Işın tedavisi hiçbir zaman kullanılmamalıdır', 'Donanım kilitleri gereksiz maliyettir', 'Hastaların cihazı kendisi ayarlamalıdır'], 'Önceki modellerdeki donanımsal güvenlik kilitleri kaldırılmış, yarış durumu içeren yazılım tek güvence olmuştu; bağımsız güvenlik katmanlarının önemi ortaya çıktı.'),
  ('1970\'lerde Ford Pinto tartışmasının odağında hangi tasarım sorunu vardı?', 'Arkadan çarpmada yakıt deposunun delinip yangın riski yaratması', ['Fren sisteminin yağmurda çalışmaması', 'Ön camın güneşte erimesi', 'Lastiklerin yüksek hızda patlaması'], 'Depo konumu arkadan çarpmalarda yangına yol açabiliyordu; firmanın iyileştirme maliyetiyle olası tazminatları karşılaştıran iç hesapları ciddi etik eleştiri aldı.'),
  ('1978\'de New York\'taki Citicorp Center gökdeleninde yapısal mühendis William LeMessurier ne yaptı?', 'Tasarımındaki rüzgâr kusurunu fark edip açıklayarak gizlice onarım başlattı', ['Kusuru gizleyip binayı satışa çıkardı', 'Binanın yıkılmasını istedi', 'Kusuru başka bir mühendise yükledi'], 'Çapraz rüzgârlar ve bulonlu bağlantılar nedeniyle risk fark edilince LeMessurier sorumluluğu üstlendi; bağlantılar geceleri kaynakla güçlendirildi.'),
  ('Dieselgate vakası öncelikle hangi etik ilkenin ihlaline örnektir?', 'Dürüstlük ve kamuyu yanıltmama', ['Yetkinlik sınırlarına uyma', 'Meslektaşlara ücret indirimi yapmama', 'Ticari sırrı koruma'], 'Düzenleyicileri ve müşterileri yanıltmak için bilerek tasarlanmış bir yazılım, dürüstlük ve kamu sağlığını koruma ilkelerini birlikte çiğner.'),
  ('İhtiyatlılık ilkesi (precautionary principle) neyi savunur?', 'Ciddi zarar olasılığında bilimsel kesinlik beklemeden önlem alınmasını', ['Kanıt kesinleşene dek hiçbir önlem alınmamasını', 'Riskli ürünlerin önce piyasaya sürülüp sonra incelenmesini', 'Yalnız ekonomik çıkarların dikkate alınmasını'], '1992 Rio Bildirgesi\'nde de yer alan ilkeye göre geri dönüşü olmayan zarar tehdidinde bilimsel belirsizlik önlemleri ertelemek için gerekçe olamaz.'),
  ('Bir mühendis, yaşlıların ve engellilerin de kullanabileceği bir istasyon tasarlamak için \'evrensel tasarım\' ilkelerini uyguluyor. Bu yaklaşım neyi amaçlar?', 'Ürünün olabildiğince çok kişi tarafından uyarlama gerekmeden kullanılması', ['Ürünün yalnız ortalama kullanıcıya göre tasarlanması', 'Engelliler için ayrı ve gizli girişler yapılması', 'Tasarımın tek bir ülkenin standardına göre yapılması'], 'Evrensel tasarım rampalar, okunaklı işaretler, dokunsal yüzeyler gibi çözümlerle herkesin eşit kullanımını hedefler.'),
  ('Faydacı (sonuççu) etik yaklaşımı bir mühendislik kararını hangi ölçüte göre değerlendirir?', 'Sonuçların toplam iyiliğine', ['Kuralın evrensel olup olmadığına', 'Kararı verenin karakter erdemlerine', 'Kararın geleneklere uygunluğuna'], 'Faydacılık en çok kişi için en büyük iyiliği gözetir; görev etiği ise sonuçtan bağımsız olarak uyulması gereken ödevleri öne çıkarır.'),
  ('Kant\'çı görev etiğine göre bir mühendis için hangi davranış her durumda yanlıştır?', 'Müşteriyi kendi çıkarı için kandırmak', ['Kârlı bir projeyi kabul etmek', 'Daha ucuz bir malzeme önermek', 'Ekip arkadaşının hatasını düzeltmek'], 'Görev etiğinde insanlara yalnız araç olarak davranmak ve aldatmak, sonuç ne olursa olsun yanlıştır.'),
  ('Bir şirketin güvenlik kültürünün güçlü olduğuna dair en iyi gösterge hangisidir?', 'Çalışanların hataları ceza korkusu olmadan bildirebilmesi', ['Kazaların hiçbir zaman kayda geçmemesi', 'Yalnız yöneticilerin güvenlik kararı vermesi', 'Güvenlik eğitiminin yalnız ilk gün verilmesi'], 'Raporlanmayan ramak kala olaylar büyük kazaların habercisidir; açık bildirim kültürü sorunların erken düzeltilmesini sağlar.'),
  ('Bir yazılım mühendisi, otomatik bir aracın frenleme algoritmasında nadir ama ölümcül olabilecek bir hata buluyor; yöneticisi teslim tarihine uyulmasını istiyor. En savunulabilir tutum hangisidir?', 'Hatayı kayda geçirip giderilmeden yayına karşı çıkmak', ['Teslim tarihine uymak ve konuyu unutmak', 'Hatayı gizlice silmeden yayına izin vermek', 'Kodu ücretsiz olarak internete yüklemek'], 'Kamu güvenliği takvim baskısından önce gelir; mühendis riski belgeleyip bildirmeli ve gerekirse üst kademelere taşımalıdır.'),
  ('Bir mühendis bilirkişi olarak mahkemede ifade verirken hangi davranış beklenir?', 'Yalnız bildiği konularda tarafsız ve nesnel görüş bildirmek', ['Kendisini atayan tarafın lehine her durumda konuşmak', 'Bilmediği konularda tahminde bulunup kesin konuşmak', 'Ücretine göre görüşünü değiştirmek'], 'Meslek kuralları, kamuya açık açıklamalarda ve bilirkişilikte mühendisin nesnel, dürüst ve yetkinliği içinde kalmasını ister.'),
  ('Bir fabrikada çalışan mühendis, rakip firma hakkında asılsız olumsuz söylentiler yayıyor. Bu davranış meslek kurallarının hangisine aykırıdır?', 'Meslektaşların itibarını haksız yere zedelememek', ['Ticari sırrı korumak', 'Sürekli eğitim almak', 'Yetkinlik sınırına uymak'], 'Meslek kuralları mühendislerin başka mühendislerin itibarını ve işini kötü niyetle ya da yanlış beyanla zedelememesini ister.'),
  ('Etik vakalarda \'ramak kala\' (near miss) olaylarının kaydedilip incelenmesinin önemi nedir?', 'Henüz zarar olmadan risk örüntülerini ortaya çıkarması', ['Çalışanları cezalandırmak için kanıt toplaması', 'Sigorta primlerini otomatik düşürmesi', 'Kazaların istatistikten silinmesini sağlaması'], 'Ağır kazalar çoğu zaman benzer ramak kala olaylarıyla önceden haber verir; bunları incelemek önleyici düzeltme sağlar.'),
  ('Mühendislik etik kurallarının bir mühendise \'kamuya açık açıklamalarda nesnel ve dürüst olma\' görevi yüklemesinin temel gerekçesi nedir?', 'Kamu, teknik konularda uzman görüşüne güvenerek karar verir', ['Mühendislerin basında daha çok görünmesi istenir', 'Açıklamaların reklam geliri getirmesi gerekir', 'Mühendisler siyasetçilerden daha yetkilidir'], 'Teknik bilgisi olmayan kamu uzmanlara güvenir; yanıltıcı açıklama bu güveni kötüye kullanmak olur.'),
  ('Problem tanımında \'çözümü tanımın içine gömmek\' neden sakıncalıdır?', 'Seçenekleri baştan daraltır', ['Tasarımcının işini gereğinden çok kolaylaştırır ve süreyi kısaltır', 'Problemi yasal açıdan geçersiz kılar ve projeyi durdurur', 'Müşterinin bütçesini kendiliğinden iki katına çıkarır'], '\'Daha hızlı bir asansör yap\' yerine \'insanlar beklemekten şikâyetçi\' demek, ayna koymak gibi beklenmedik çözümlere de kapı açar.'),
  ('\'Beş neden\' (5 Why) tekniği tasarım sürecinde ne için kullanılır?', 'Kök nedeni bulmak', ['Beş farklı ürün rengi arasından en çok beğenileni seçmek için', 'Proje bütçesini beş eşit parçaya bölmek için', 'Prototipi beş kez üst üste test edip ortalamasını almak için'], 'Bir sorunun nedenine art arda \'neden?\' diye sorularak yüzeydeki belirtiden alttaki temel nedene inilir; teknik Toyota üretim sisteminde yaygınlaşmıştır.'),
  ('Kalite işlev göçerimi (QFD) ve \'kalite evi\' matrisinin temel amacı nedir?', 'Müşteri isteklerini teknik özelliklere bağlamak', ['Fabrikadaki işçilerin vardiya çizelgesini çıkarmak ve izinleri planlamak', 'Ürünün reklam filminin senaryosunu yazmak', 'Ürünün gümrük vergisini hesaplamak ve beyan etmek'], 'QFD, \'müşterinin sesi\'ni ölçülebilir mühendislik parametrelerine çevirir ve hangi parametrenin hangi isteği ne kadar etkilediğini gösterir.'),
  ('Kano modeline göre bir otomobilde fren sistemi hangi sınıfa girer?', 'Temel beklenti', ['Heyecan verici özellik', 'İlgisiz özellik', 'Ters özellik'], 'Müşteri frenin çalışmasını zaten bekler; iyi çalışması büyük coşku yaratmaz ama çalışmaması büyük hoşnutsuzluk doğurur.'),
  ('TRIZ\'de \'teknik çelişki\' ne demektir?', 'Bir parametreyi iyileştirince başka birinin kötüleşmesi', ['İki mühendisin aynı projede anlaşmazlığa düşmesi ve tartışması', 'Patent başvurusunda iki farklı tarih yazılması', 'Bir ürünün iki farklı renkte üretilmesi ve karışması'], 'Örneğin bir kutunun dayanımını artırmak için kalınlaştırmak ağırlığı da artırır; TRIZ çelişkiyi ödünleşim yerine yaratıcı ilkelerle çözmeyi amaçlar.'),
  ('Japonya\'daki Shinkansen hızlı treninin burun biçiminin yeniden tasarımında hangi kuştan esinlenildiği bilinir?', 'Yalıçapkını', ['Penguen', 'Devekuşu', 'Tavuk'], 'Tünele girerken oluşan basınç dalgası ve gürültüyü azaltmak için suya sıçramadan dalan yalıçapkınının gagası örnek alındı.'),
  ('Beyin fırtınasına göre \'beyin yazımı\' (brainwriting) yönteminin bir üstünlüğü nedir?', 'Sessiz katılımcılar da fikir üretir', ['Toplantının yalnız bir kişi tarafından yönetilmesini zorunlu kılar', 'Fikirlerin anında eleştirilip elenmesini sağlar', 'Toplantının mutlaka iki gün sürmesini gerektirir'], 'Fikirler kâğıda yazılıp elden ele geçtiği için baskın kişilerin etkisi azalır ve herkes eşit katkı verir; 6-3-5 yöntemi buna örnektir.'),
  ('Bir ekip yeni bir tasarımı önce gerçek kullanıcıların yaptığı kâğıt eskizlerle sınayıp sonra yazılıma geçiyor. Bu yaklaşımın adı nedir?', 'Düşük doğrulukta prototipleme', ['Seri üretim sonrası alan denemesi ve geri çağırma', 'Yüksek maliyetli pilot tesis kurulumu ve devreye alma', 'Son kullanıcıya yönelik garanti uygulaması'], 'Kâğıt ve karton prototipler çok ucuzdur, birkaç saatte değiştirilebilir ve temel kullanım sorunlarını erken yakalar.'),
  ('Bir prototip testinden önce ekibin \'bu testle neyi öğrenmek istiyoruz\' sorusunu yanıtlaması neden önemlidir?', 'Testin ölçütü ve yöntemi buna göre seçilir', ['Testin süresi mutlaka bir haftayı aşmalıdır', 'Test sonuçlarının raporlanmasına gerek kalmaz', 'Prototipin rengi bu soruya göre belirlenir'], 'Açık bir test sorusu, hangi verinin toplanacağını ve başarının neye göre değerlendirileceğini belirler; aksi hâlde test sonuçsuz kalabilir.'),
  ('Yeni bir sandalyenin dayanıklılık testinde, sandalyeye binlerce kez yük bindirip kaldıran makine kullanılıyor. Bu testle öncelikle hangi arıza türü sınanır?', 'Yorulma', ['Korozyon nedeniyle oluşan yüzey çürümesi', 'Isıl genleşmeden doğan renk değişimi', 'Ultraviyole ışık altında solma'], 'Tekrarlı yükleme bağlantı noktalarında yorulma çatlaklarını ortaya çıkarır; bu tür hızlandırılmış testler yılların kullanımını kısa sürede taklit eder.'),
  ('Tasarım düşüncesinde \'Nasıl yapabiliriz ki…?\' (How might we) soruları hangi aşamada kullanılır?', 'Problemi fikir üretmeye açacak biçimde çerçevelerken', ['Ürünün fiyat etiketini basarken ve rafa dizerken', 'Fabrikada makine bakımı yaparken', 'Ürünün geri dönüşüm kodunu seçerken'], 'Bu sorular tanımlanmış problemi iyimser ve açık uçlu biçimde ifade ederek fikir üretme oturumunu başlatır.'),
  ('Kullanıcı yolculuğu haritası (customer journey map) bir tasarım ekibine ne sağlar?', 'Kullanıcının deneyimini adım adım görmeyi', ['Fabrikanın kat planını ve makine yerleşimini', 'Ürünün teknik resmindeki ölçü zincirini', 'Şirketin yıllık mali tablolarını ve bilançosunu'], 'Harita, kullanıcının bir hizmetle temas noktalarını, duygularını ve sorun yaşadığı anları sırayla gösterir.'),
  ('\'Iraksak\' ve \'yakınsak\' düşünme tasarım sürecinde nasıl kullanılır?', 'Önce seçenek çoğaltılır, sonra elenir', ['Önce tek fikir seçilir, sonra hiç değiştirilmez', 'İkisi de yalnız üretim aşamasında uygulanır', 'Iraksak düşünme yalnız bütçe hesabında kullanılır'], 'Çift elmas modelinde ekip önce geniş biçimde keşfeder ve fikir üretir (ıraksak), sonra en uygununa odaklanır (yakınsak).'),
  ('Bir ekip ilk fikrine hemen bağlanıp başka seçenekleri hiç değerlendirmiyor. Bu tasarım hatasına ne ad verilir?', 'Erken sabitlenme', ['Değer mühendisliği', 'Paralel mühendislik', 'Kalibrasyon kayması'], 'Erken sabitlenme (fixation), ekibin daha iyi olabilecek alternatifleri görmesini engeller; birden çok kavram üretmek bunun ilacıdır.'),
  ('Eş zamanlı (paralel) mühendislik yaklaşımı neyi amaçlar?', 'Tasarım ve üretim ekiplerinin baştan birlikte çalışmasını', ['Her bölümün işini bitirip ötekine devretmesini ve beklemesini', 'Tasarımın tamamen dış firmaya bırakılmasını', 'Ürünün yalnız tek bir mühendis tarafından çizilmesini'], 'Üretim, kalite, satın alma gibi birimlerin erken katılımı sonradan çıkacak sorunları önler ve geliştirme süresini kısaltır.'),
  ('Bir hata ağacında tepe olay iki bağımsız olayın \'VE\' kapısıyla birleşmesine bağlı. Olasılıklar 0,01 ve 0,02 ise tepe olayın olasılığı kaçtır?', '0,0002', ['0,03', '0,02', '0,0102'], 'VE kapısında her iki olayın birlikte olması gerekir; bağımsız olaylar için 0,01 × 0,02 = 0,0002.'),
  ('Bir otobüs kapısının genişliği belirlenirken hangi yüzdelik dilime göre tasarlanması gerekir?', 'Büyük gövdeli kullanıcılar (üst yüzdelik)', ['En dar omuzlu kullanıcılar (alt yüzdelik)', 'Yalnız ortalama kullanıcı', 'Yalnız okul çağındaki çocuk yolcuların omuz genişliği'], 'Açıklık (geçiş) boyutları en büyük kullanıcının da geçebileceği şekilde üst yüzdelikten seçilir; erişim boyutları ise kısa kollu kullanıcıya göre alt yüzdelikten seçilir.'),
  ('Bir USB belleğin yalnız tek yönde takılabilmesi ya da bir SIM kartın köşesinin kesik olması hangi tasarım ilkesine örnektir?', 'Hata önleme', ['Planlı eskitme', 'Değer analizi ile maliyet artırma', 'Yinelemeli test ve doğrulama'], 'Poka-yoke, Shigeo Shingo\'nun yaygınlaştırdığı, yanlış kullanımı fiziksel olarak olanaksız ya da hemen fark edilir kılan hata önleme yaklaşımıdır.'),
  ('Bir kapının itilmesi gerektiği hâlde üzerine çekme kolu takılması hangi tasarım hatasıdır?', 'Yanıltıcı olanak sunumu', ['Fazla dar tolerans verilmesi', 'Malzemenin yanlış ısıl işlem görmesi', 'Yüzey pürüzlülüğünün düşük tutulması'], 'Kol biçimi \'çek\' mesajı verir; kullanıcı yanlış eylemi dener. Bu tür kapılar Norman kapısı olarak bilinir; itilecek kapıya düz plaka konmalıdır.'),
  ('Modüler tasarımın sürdürülebilirliğe katkısı hangi örnekle en iyi açıklanır?', 'Arızalı bir telefon kamerasının tek başına değiştirilebilmesi', ['Telefonun tamamen yapıştırılarak tek parça üretilmesi', 'Bataryanın gövdeyle kaynaklanması', 'Her yıl yeni ve eskisiyle uyumsuz bir şarj aleti standardı çıkarılması'], 'Modüler yapı onarımı ve yükseltmeyi kolaylaştırır; ürünün ömrü uzar, atık azalır.'),
  ('Karbon ayak izi hesaplamasında \'CO₂ eşdeğeri\' kavramı neden kullanılır?', 'Farklı sera gazlarını tek ölçekte toplamak için', ['Yalnız karbondioksitin rengini belirtmek için', 'Atmosferdeki oksijen oranını ölçmek için', 'Kömürün ve petrolün dünya piyasa fiyatını sabitlemek için'], 'Metan, azot protoksit gibi gazların ısınma etkileri CO₂\'ye göre çarpanlarla ifade edilir; böylece tek bir toplam elde edilir.'),
  ('İzometrik perspektifte üç ana eksen arasındaki açılar kaçar derecedir?', '120', ['90', '60', '135'], 'İzometrik perspektifte eksenler birbirine 120° açıyla görünür ve üç eksende ölçek eşittir.'),
  ('\'Değiştirilebilirlik\' ilkesinin seri üretimdeki önemi nedir?', 'Herhangi bir parça seçmeden takılabilir', ['Her parçanın kendi deliğine özel olarak alıştırılması', 'Parçaların farklı fabrikalarda hiç üretilememesi', 'Her ürünün tek tek elle ayarlanması'], 'Tolerans sistemi sayesinde aynı ölçülü parçalar birbirinin yerine geçer; Eli Whitney ve Honoré Blanc gibi öncüler bu fikri tüfek üretiminde uygulamıştır.'),
  ('Bir CAD modelinde \'parametrik\' tasarımın anlamı nedir?', 'Geometri ölçü ve kısıtlarla tanımlanır', ['Model yalnız rastgele noktalardan oluşur', 'Model yalnız iki boyutlu çizgilerden ibarettir', 'Model hiçbir zaman değiştirilemez'], 'Parametrik modelde bir çap ya da boy değiştirildiğinde ona bağlı unsurlar ilişkilerine göre güncellenir.'),
  ('Bir firma ürününü fiziksel olarak üretmeden önce dijital ikizini oluşturuyor. Dijital ikiz kavramının temel özelliği nedir?', 'Gerçek sistemin verileriyle güncellenen sanal modeldir', ['Ürünün kopyalanıp başka firmaya satılmasıdır', 'Ürünün iki farklı renkte çizilmesidir', 'Ürünün katalogda yer alan yalnız pazarlama amaçlı fotoğrafıdır'], 'Dijital ikiz, algılayıcılardan gelen verilerle güncellenen ve gerçek sistemin davranışını izlemeye, tahmin etmeye yarayan sanal temsildir.'),
  ('CAD modelinden doğrudan takım yolu üretip tezgâhı yöneten yazılım sistemine ne ad verilir?', 'CAM', ['CAE', 'PLM', 'ERP sistemi'], 'CAM (bilgisayar destekli imalat), CNC tezgâhları için kesme yollarını ve G-kodunu oluşturur; CAE ise mühendislik analizlerini kapsar.'),
  ('Sonlu elemanlar analizinde ağ (mesh) sıklığının artırılması genellikle neye yol açar?', 'Daha doğru sonuç, daha uzun hesap süresi', ['Daha kısa hesap süresi ve her zaman daha kötü sonuç', 'Malzeme özelliklerinin kendiliğinden değişmesi', 'Sınır koşullarının yok olması'], 'Daha çok eleman çözümü gerçeğe yaklaştırır ama hesap yükünü artırır; ağ yakınsama çalışması uygun sıklığı bulmaya yarar.'),
  ('ISO\'nun açılımı ve merkezi için hangi bilgi doğrudur?', 'Uluslararası Standardizasyon Örgütü, Cenevre', ['Uluslararası Sanayi ve Ticaret Ofisi, Paris', 'Uluslararası Güvenlik Örgütü, New York', 'Avrupa Standartlar Birliği, Brüksel'], 'ISO 1947\'de kurulmuş, merkezi İsviçre\'nin Cenevre kentinde bulunan uluslararası standart kuruluşudur.'),
  ('Bir firmanın ürününün standartlara uygunluğunu kendisi beyan etmesi yerine bağımsız bir kuruluşa belgelendirmesinin müşteriye sağladığı temel yarar nedir?', 'Tarafsız üçüncü taraf güvencesi', ['Ürünün kendiliğinden daha ucuz olması', 'Ürünün hiç test edilmemesi', 'Standartların bir daha değişmemesi'], 'Üçüncü taraf belgelendirme, çıkar çatışması olmayan bir denetçinin uygunluğu doğruladığını gösterir.'),
  ('Bir projede bir etkinliğin süresi iyimser 4, en olası 6, kötümser 14 gün tahmin ediliyor. PERT yöntemine göre beklenen süre kaç gündür?', '7', ['6', '8', '24'], 'PERT beklenen süresi (a + 4m + b) / 6 = (4 + 24 + 14) / 6 = 42 / 6 = 7 gündür.'),
  ('Proje yönetiminde \'iş kırılım yapısı\' (WBS) ne işe yarar?', 'Projeyi yönetilebilir iş paketlerine bölmeye', ['Çalışanların özlük dosyalarını saklamaya', 'Malzeme stoklarını tartmaya', 'Ürünün teknik resmini ve montaj çizimini otomatik üretmeye'], 'WBS, proje kapsamını hiyerarşik olarak daha küçük ve tahmin edilebilir iş paketlerine ayırır.'),
  ('Aynı malzemeden yapılmış iki çubuktan birinin çapı diğerinin iki katıdır. Aynı çekme kuvveti altında kalın çubuktaki gerilme incedekinin kaç katıdır?', '1/4', ['2 katı, çünkü çap iki katına çıkmıştır', '4 katı', '1/2, çünkü gerilme çapla ters orantılıdır'], 'Kesit alanı çapın karesiyle artar; çap iki kat olunca alan dört kat olur ve gerilme dörtte birine iner.'),
  ('Bir çelik telin boyu iki katına çıkarılırsa, aynı yük altında toplam uzaması nasıl değişir?', 'İki katına çıkar', ['Değişmez, çünkü uzama yalnız malzemeye bağlıdır', 'Yarıya iner, çünkü uzun tel daha rijittir', 'Dört katına çıkar, çünkü uzama boyun karesiyle artar'], 'ΔL = F·L / (A·E); diğer büyüklükler sabitken uzama boyla doğru orantılıdır.'),
  ('Bir anahtarla somun sıkılırken anahtarın sapı esas olarak hangi tür zorlanmaya maruz kalır?', 'Eğilme', ['Saf eksenel çekme', 'Hidrostatik basınç', 'Sünme'], 'Ucundan kuvvet uygulanan sap bir konsol kiriş gibi davranır; bir yüzünde çekme, öbür yüzünde basma oluşur.'),
  ('Bir milin bir ucundan döndürülüp diğer ucunun tutulması mil kesitinde hangi gerilmeyi doğurur?', 'Burulmadan doğan kayma gerilmesi', ['Yalnız eksenel çekme ve buna bağlı uzama', 'Yalnız basma', 'Isıl genleşme gerilmesi'], 'Burulma momenti kesitte kayma gerilmesi oluşturur; gerilme mil ekseninde sıfır, dış yüzeyde en büyüktür.'),
  ('Bir kirişin ortasında açılan delik, delik kenarında gerilmenin yerel olarak artmasına yol açar. Bu olaya ne ad verilir?', 'Gerilme yığılması', ['Sünme dayanımı ile birlikte gerilme gevşemesi', 'Pekleşme', 'Isıl yorulma'], 'Delik, çentik ve keskin köşeler çevresinde gerilme nominal değerin birkaç katına çıkabilir; geniş levhadaki dairesel delikte bu çarpan yaklaşık 3\'tür.'),
  ('Çekme deneyinde kuvvet-uzama verileri yerine gerilme-şekil değiştirme eğrisinin kullanılmasının nedeni nedir?', 'Numune boyutundan bağımsız sonuç', ['Eğrinin her zaman doğrusal olması', 'Grafiğin daha renkli görünmesi', 'Yalnız kuvvetin ölçülebilmesi'], 'Gerilme ve gerinim, kuvveti alana ve uzamayı boya böldüğü için farklı boyutlu numunelerin sonuçları karşılaştırılabilir.'),
  ('Kauçuğun gerilme-şekil değiştirme davranışı çeliğinkinden nasıl ayrılır?', 'Çok büyük ve doğrusal olmayan elastik uzama', ['Kauçuk hiç elastik davranış göstermez', 'Kauçuğun elastisite modülü çelikten büyüktür', 'Kauçuk yük altında hiç uzamaz'], 'Elastomerler yüzlerce yüzde uzayıp geri dönebilir; zincirlerin düzleşmesi nedeniyle eğri doğrusal değildir.'),
  ('Rezilyans (esneklik enerjisi) kavramı neyi ifade eder?', 'Elastik bölgede depolanan enerji', ['Kırılmaya kadar soğurulan toplam enerjinin iki katı', 'Malzemenin sertlik değeri', 'Malzemenin ısıyı depolama yeteneği'], 'Rezilyans, akma noktasına kadar eğri altında kalan alandır; yay malzemelerinde yüksek olması istenir.'),
  ('Bir yay malzemesi seçilirken hangi özellik karması istenir?', 'Yüksek akma dayanımı, uygun elastisite modülü', ['Düşük akma dayanımı ve çok yüksek süneklik', 'Yüksek ısıl iletkenlik ve düşük ergime noktası', 'Çok yüksek gevreklik ve şeffaflık'], 'Yay büyük elastik şekil değiştirmeyi kalıcı biçim değiştirmeden geri vermelidir; bu yüzden yüksek akma dayanımlı yay çelikleri kullanılır.'),
  ('Dökme demir genellikle hangi yüklemede kullanıma daha uygundur?', 'Basma', ['Darbeli çekme', 'Yüksek gerinimli eğme', 'Tekrarlı burulma'], 'Gevrek dökme demirin basma dayanımı yüksek, çekme ve darbe dayanımı düşüktür; makine gövdeleri ve tabanlarında kullanılır.'),
  ('Bir malzemenin hem sünek hem dayanıklı olması tokluk açısından ne anlama gelir?', 'Tokluk yüksektir', ['Tokluk sıfırdır, çünkü iki özellik birbirini götürür', 'Tokluk yalnız sertliğe bağlıdır', 'Tokluk yalnız rengiyle ilişkilidir'], 'Tokluk, dayanım ile şekil değiştirme yeteneğinin birlikte bir ölçüsüdür; eğri altındaki alan büyür.'),
  ('Cam ve çelik karşılaştırıldığında, cam daha sert olduğu hâlde darbeyle neden daha kolay kırılır?', 'Tokluğu çok düşüktür', ['Camın yoğunluğu çelikten çok daha yüksektir', 'Camın elastisite modülü sıfırdır', 'Cam elektriği çelikten iyi iletir'], 'Sertlik çizilmeye ve batmaya direnç, tokluk ise kırılmaya kadar enerji soğurmadır; cam sert ama gevrektir.'),
  ('Rockwell C (HRC) ölçeği genellikle hangi malzemeler için kullanılır?', 'Sertleştirilmiş çelikler', ['Yumuşak kurşun ve kalay', 'Ahşap, mantar ve benzeri gözenekli malzemeler', 'Köpük plastikler'], 'HRC ölçeği elmas koni uç ve 150 kgf toplam yükle sert çeliklerde kullanılır; yumuşak metallerde B ölçeği (bilye uç) tercih edilir.'),
  ('Çelik üretiminde kullanılan ark ocağının (elektrik ark fırını) başlıca hammaddesi hangisidir?', 'Hurda çelik', ['Ham petrol', 'Kum ve kireç taşı yalnızca', 'Boksit cevheri'], 'Elektrik ark fırınları ağırlıklı olarak hurda çeliği ergiterek yeniden çelik üretir; bu da geri dönüşüme önemli katkı sağlar.'),
  ('Çelikte kükürt ve fosfor gibi elementlerin oranının düşük tutulmasının nedeni nedir?', 'Gevrekliğe yol açarlar', ['Çeliği daha sünek ve tok yaparlar', 'Çeliğin rengini güzelleştirirler', 'Çeliği paslanmaz hâle getirirler'], 'Kükürt sıcak gevrekliğe, fosfor soğuk gevrekliğe neden olur; bu yüzden istenmeyen safsızlıklar olarak sınırlanır.'),
  ('Çeliğin yüzeyine azot yayındırarak sert nitrür tabakası oluşturan işlem hangisidir?', 'Nitrürleme', ['Normalizasyon', 'Galvanizleme', 'Vulkanizasyon'], 'Nitrürleme görece düşük sıcaklıkta yapılır ve su verme gerektirmediği için çarpılma azdır.'),
  ('Alüminyum içecek kutularının geri dönüştürülmesi neden çok büyük enerji tasarrufu sağlar?', 'Cevherden üretim çok enerji ister', ['Alüminyum geri dönüştürüldükçe ağırlık kazanır', 'Geri dönüşüm alüminyumu altına dönüştürür', 'Alüminyum hiç erimeden yeniden şekillenir'], 'Boksitten elektrolizle alüminyum üretmek çok elektrik tüketir; hurdayı ergitmek bu enerjinin yalnız yaklaşık yüzde beşini gerektirir.'),
  ('Şekil hafızalı alaşımlara en bilinen örnek hangisidir?', 'Nikel-titanyum (Nitinol)', ['Bakır-kalay (bronz)', 'Kurşun-kalay (lehim)', 'Demir-karbon (dökme demir)'], 'Nitinol, deforme edildikten sonra ısıtılınca önceki biçimine döner; gözlük çerçeveleri ve tıbbi stentlerde kullanılır.'),
  ('Aynı element farklı sıcaklıklarda farklı kristal yapılarda bulunabiliyorsa bu özelliğe ne ad verilir?', 'Allotropi', ['İzotopi', 'Anizotropi', 'Amorfluk'], 'Demirin α (HMK) ve γ (YMK) biçimleri ile karbonun elmas ve grafit biçimleri allotropiye örnektir.'),
  ('Faz diyagramı bir alaşım sistemi için neyi gösterir?', 'Sıcaklık ve bileşime göre kararlı fazları', ['Alaşımın fiyatının yıllara göre değişimini', 'Alaşımı üreten ülkelerin listesini ve üretim miktarlarını', 'Alaşımdan yapılan ürünlerin satış grafiğini'], 'Denge faz diyagramları belirli bileşim ve sıcaklıkta hangi fazların bulunduğunu, oranlarını ve ergime aralığını gösterir.'),
  ('Ötektik bileşimdeki bir alaşımın özelliği nedir?', 'Tek bir en düşük sıcaklıkta erir', ['Hiçbir sıcaklıkta erimez', 'Her zaman saf metallerden daha yüksek sıcaklıkta erir', 'Erime sırasında renk değiştirip şeffaflaşır'], 'Ötektik bileşimde sıvı, sistemin en düşük ergime sıcaklığında doğrudan iki katı faza dönüşür; geleneksel kalay-kurşun lehimi bu yüzden ötektiğe yakın seçilirdi.'),
  ('Polimerlerin çoğunun güneş ışığında zamanla sararıp gevrekleşmesinin başlıca nedeni nedir?', 'Ultraviyole ışınların zincirleri kırması', ['Plastiğin güneşte metale dönüşmesi', 'Güneş ışığının plastiğin kütlesini artırması', 'Polimerin güneşte süper iletken olması'], 'UV ışınları kimyasal bağları kırarak zincir boyunu kısaltır; bu yüzden dış ortam plastiklerine UV dengeleyici katılır.'),
  ('Kompozit malzemelerde \'matris\'in görevi hangisidir?', 'Lifleri bir arada tutup yükü onlara aktarmak', ['Malzemeye yalnız renk ve parlaklık vermek, yük taşımamak', 'Liflerin yerine tüm yükü tek başına taşımak', 'Malzemeyi her zaman iletken yapmak'], 'Matris lifleri yerinde tutar, aralarında yük aktarır ve onları çevresel etkilerden korur.'),
  ('Nanomalzemeler genellikle en az bir boyutu hangi ölçek aralığında olan malzemeler olarak tanımlanır?', '1–100 nanometre', ['1–100 milimetre', '1–100 metre', '1–100 mikrometre'], 'Bu ölçekte yüzey/hacim oranı ve kuantum etkileri nedeniyle malzemeler farklı özellikler gösterebilir.'),
  ('Grafen hangi yapıya sahiptir?', 'Tek atom kalınlığında karbon katmanı', ['Üç boyutlu elmas kristali', 'Karbon ve silisyumdan oluşan cam', 'Karbon atomlarının rastgele dizildiği amorf toz'], 'Grafen, bal peteği düzeninde dizilmiş tek katman karbon atomlarıdır; 2010 Nobel Fizik Ödülü bu malzemeyle ilgili çalışmalara verildi.'),
  ('Sıvı penetrant muayenesinin bir sınırlaması hangisidir?', 'Yalnız yüzeye açık kusurları bulur', ['Yalnız manyetik malzemelerde uygulanabilir', 'Parçayı her zaman kırmayı gerektirir', 'Radyasyon güvenliği önlemleri olmadan yapılamaz'], 'Penetrant yüzeye açık çatlaklara sızar; iç gözenekler ve yüzeye açılmayan çatlaklar bu yöntemle görülemez.'),
  ('Gücün SI birimi watt, temel birimler cinsinden nasıl yazılır?', 'kg·m²/s³', ['kg·m/s²', 'kg·m²/s²', 'kg/(m·s²)'], '1 W = 1 J/s = 1 kg·m²/s³; kg·m²/s² joule, kg/(m·s²) ise pascaldır.'),
  ('\'Nano\' önekiyle yazılmış 450 nm kaç metredir?', '4,5 × 10⁻⁷', ['4,5 × 10⁻⁶', '4,5 × 10⁻⁹', '4,5 × 10⁻⁵'], '1 nm = 10⁻⁹ m; 450 × 10⁻⁹ = 4,5 × 10⁻⁷ m.'),
  ('Bir ölçüm raporunda \'3 mm\' yerine \'3 Mm\' yazılması neden ciddi bir hatadır?', 'Mm megametredir, yani 3000 km', ['Mm diye bir birim olmadığından rapor geçersizdir', 'Büyük harf yalnız sıcaklık birimlerinde kullanılır', 'İki gösterim aynıdır, yalnızca yazım tercihidir'], 'SI\'da önek harflerinin büyük-küçük yazılışı anlam taşır: m mili (10⁻³), M mega (10⁶) demektir.'),
  ('Bir tork anahtarı 50 N·m\'ye ayarlanmıştır. Bu değer yaklaşık kaç kgf·m\'dir? (g ≈ 9,81 m/s²)', '5,1', ['490', '50', '0,51'], '1 kgf = 9,81 N olduğundan 50 / 9,81 ≈ 5,1 kgf·m.'),
  ('Ölçüm belirsizliği ile hata arasındaki fark nedir?', 'Hata bilinemeyen bir farktır, belirsizlik bu farkın tahmini aralığıdır', ['İkisi tamamen aynı kavramdır ve birbirinin yerine kullanılır', 'Belirsizlik yalnız dijital aletlerde, hata yalnız analog aletlerde görülür', 'Hata her zaman sıfırdır, belirsizlik her zaman yüzde beştir'], 'Gerçek değer bilinmediğinden hata da tam bilinemez; belirsizlik, ölçülen değerin çevresinde gerçek değerin bulunabileceği aralığı nicel olarak ifade eder.'),
  ('Dijital bir terazide okunan \'125,0 g\' değerindeki sondaki sıfır için hangi yorum doğrudur?', 'Ölçümün onda bir grama duyarlı yapıldığını gösterir', ['Anlamsızdır; yazılmasa da sonuç aynı bilgiyi taşır', 'Terazinin bozuk olduğunu ve yeniden kalibre edilmesi gerektiğini gösterir', 'Kütlenin tam olarak 125 kg olduğunu gösterir'], 'Ondalık virgülden sonraki sıfır anlamlı basamaktır; değerin 125,0 g olarak dört anlamlı basamakla, onda bir gram duyarlılıkla ölçüldüğünü gösterir.'),
  ('Bir öğrenci 2,0 cm\'lik bir kenarın karesini hesap makinesinde 4 buluyor. Anlamlı basamak kurallarına göre sonuç nasıl yazılmalıdır?', '4,0 cm²', ['4 cm²', '4,00 cm²', '4,000 cm²'], 'Veri iki anlamlı basamaklıdır (2,0); çarpım sonucu da iki anlamlı basamakla, yani 4,0 cm² olarak yazılır.'),
  ('Bir değeri 2,45 iken bir basamağa yuvarlamada sık kullanılan \'yarıyı çifte yuvarlama\' kuralı hangi sonucu verir?', '2,4', ['2,5', '2,0', '3,0'], 'Bu kuralda tam yarı durumunda son basamak çift olacak biçimde yuvarlanır: 2,45 → 2,4. Kural uzun hesaplarda yuvarlama yanlılığını azaltır.'),
  ('Ölçü bloklarının (Johansson blokları) atölyede kullanım amacı nedir?', 'Hassas uzunluk referansı sağlamak', ['Parçaların sertliğini ölçmek', 'Sıcaklığı kontrol etmek', 'Elektrik akımını kalibre etmek ve devreyi korumak'], 'Çok düzgün yüzeyli çelik ya da seramik bloklar birbirine yapıştırılarak istenen uzunluk elde edilir ve kumpas, mikrometre gibi aletler kontrol edilir.'),
  ('Kumpasla ölçüm yaparken parçanın çeneler arasında eğik tutulması ölçümü nasıl etkiler?', 'Ölçü gerçeğinden büyük çıkar', ['Ölçü her zaman gerçeğinden küçük çıkar', 'Ölçü hiç değişmez', 'Kumpas kendiliğinden sıfırlanır'], 'Eğik tutulan parçanın çeneler arasındaki izdüşümü gerçek çaptan uzundur; çeneler ölçülen eksene dik olmalıdır.'),
  ('Bir torna tezgâhında milin salgısı komparatörle kontrol ediliyor; mil bir tur dönerken ibre en küçük 0,02, en büyük 0,07 mm gösteriyor. Toplam salgı kaç milimetredir?', '0,05', ['0,07', '0,09', '0,025'], 'Toplam gösterge değişimi en büyük ile en küçük okuma arasındaki farktır: 0,07 − 0,02 = 0,05 mm.'),
  ('Bir açıyı dakika düzeyinde ölçmek için kullanılan, verniyeli döner ölçeği olan alet hangisidir?', 'Üniversal açı gönyesi', ['Şerit metre', 'Sentil yaprakları takımı ve şablon', 'Pergel'], 'Verniyeli üniversal açı ölçerler 5 dakikaya kadar okuma sağlar; ayarlanabilir kollarıyla iç ve dış açılar ölçülür.'),
  ('Lazer mesafe ölçerlerin çoğunun uzaklığı bulmak için kullandığı ilke hangisidir?', 'Işığın gidiş-dönüş süresi ya da faz farkı', ['Işığın renginin uzaklıkla değişmesi', 'Lazerin hedefi ısıtıp sıcaklığını ölçmesi', 'Lazerin hedefe çarpınca ses çıkarması ve bunun mikrofonla algılanması'], 'Işık hızı bilindiğinden yansıyan ışığın dönüş süresinden ya da modüle edilmiş sinyalin faz farkından mesafe hesaplanır.'),
  ('ABD\'deki Ulusal Profesyonel Mühendisler Derneği\'nin (NSPE) etik kurallarına göre bir mühendisin mesleki görüşü kamu güvenliğini tehlikeye atan bir kararla reddedildiğinde ne yapması beklenir?', 'İşverenini ve gerekirse yetkili makamları bilgilendirmek', ['Kararı sessizce kabul edip uygulamak', 'Projeden ayrılıp kimseye bir şey söylememek', 'Kararı veren yöneticiyle ilişkisini kesip konuyu kapatmak'], 'NSPE kuralları, mühendisin yaşamı ya da malı tehlikeye atan durumlarda işverenine ve uygun görülen diğer makamlara bildirimde bulunmasını ister.'),
  ('Bir mühendisin aynı anda hem tasarımcı hem de o tasarımın bağımsız denetçisi olması neden sorunludur?', 'Kendi işini nesnel denetleyemez', ['Denetim işi tasarım işinden daha az ücretlidir', 'Yasalar iki iş yapmayı her durumda yasaklar', 'Denetçinin tasarımdan hiç anlaması gerekmez'], 'Bağımsız denetim, tasarımdaki hataları başka bir gözün yakalamasına dayanır; aynı kişinin iki rolü üstlenmesi çıkar çatışması doğurur.'),
  ('Bir mühendis, yöneticisinin baskısıyla güvenlik testini atlayan bir raporu imzalıyor ve bir kaza oluyor. Mesleki sorumluluk açısından hangi değerlendirme doğrudur?', 'İmzalayan mühendis de sorumludur', ['Yalnız yönetici sorumludur, mühendis hiç sorumlu değildir', 'Sorumluluk yalnız ürünü kullanan kişidedir', 'Kaza doğal afet sayılır ve kimse sorumlu değildir'], 'Mühür ve imza kişisel bir beyandır; baskı altında atılması mühendisi mesleki ve hukuki sorumluluktan kurtarmaz.'),
  ('Bir otomobil şirketi hatalı bir parçayı geri çağırmak yerine yalnız şikâyet eden müşterilerin parçasını sessizce değiştiriyor. Bu uygulama neden etik açıdan sorunludur?', 'Diğer kullanıcılar riskten habersiz kalır', ['Geri çağırma her zaman daha ucuz olduğu için', 'Parça değişimi yasalarca hiçbir zaman yapılamadığı için', 'Müşteriler şikâyet etmeyi sevmediği için'], 'Bilinen bir güvenlik riskini tüm etkilenenlere bildirmemek, kamu güvenliğini öncelemek ve dürüst olmak ilkeleriyle çelişir.'),
  ('Bir mühendis bir ilaç fabrikasında temiz oda tasarlıyor ve müşterinin istediği filtre sınıfının standarda göre yetersiz olduğunu biliyor. Müşteri ısrar ederse en uygun davranış nedir?', 'Standardı açıklayıp yetersiz çözümü onaylamamak', ['Müşteri her zaman haklıdır diyerek uygulamak', 'Filtreyi gizlice daha ucuz bir modelle değiştirmek', 'Projeyi bitirip sorunu sonraki mühendise bırakmak'], 'Mühendis kamu sağlığını etkileyen standart dışı bir tasarımı onaylamamalı; gerekçesini yazılı olarak bildirmelidir.'),
  ('Etik ikilemlerde kullanılan \'tersine çevirme\' (reversibility) testi hangi soruyu sorar?', 'Kararın etkilediği kişi ben olsaydım razı olur muydum?', ['Bu karar geri alınabilir mi?', 'Bu karar kaç günde uygulanır?', 'Bu karar şirketin borsadaki hisselerini ve kârını artırır mı, artırmaz mı?'], 'Test, altın kurala benzer biçimde, kararın başkalarına yüklediği maliyeti kendimiz için de kabul edip etmeyeceğimizi sorgular.'),
  ('Bir mühendisin fikrini bir patente konu etmeden önce ayrıntılı tarihli defter (laboratuvar defteri) tutması neden önerilir?', 'Buluşun tarihini ve sahipliğini kanıtlamak', ['Defterin kendisinin patent belgesi sayılması', 'Defterin yasal olarak her yıl yenilenmesi gerekmesi', 'Defter tutmanın vergi indirimi sağlaması'], 'Tarihli ve imzalı kayıtlar fikri mülkiyet uyuşmazlıklarında buluşun kimin tarafından ne zaman yapıldığını belgelemeye yardım eder.'),
  ('Bir proje yöneticisi bir etkinliği hızlandırmak için ek kaynak koyup süreyi kısaltıyor. Bu proje yönetimi tekniğine ne ad verilir?', 'Süre kısaltma', ['İş kırılım yapısı oluşturma', 'Kaynak dengeleme ile süre uzatma', 'Kapsam kayması'], 'Crashing\'de kritik yoldaki etkinliklere ek kaynak verilerek proje süresi kısaltılır; bunun maliyeti kazanılan süreyle karşılaştırılır.'),
  ('Proje planında \'kilometre taşı\' neyi temsil eder?', 'Süresi olmayan önemli bir ara hedefi', ['En uzun süren etkinliği', 'Projenin bütçesinin tamamını', 'Proje boyunca her gün yapılan sıradan ve rutin işleri'], 'Kilometre taşları örneğin \'prototip onayı\' gibi önemli noktaları işaretler; kendileri süre taşımaz.'),
  ('\'Montaj için tasarım\' (DFA) yaklaşımında bir parçanın montajda iki yöne de doğru takılabilecek biçimde simetrik yapılmasının yararı nedir?', 'Montaj hızlanır, hata azalır', ['Parçanın dayanımını iki katına çıkarır', 'Parçanın rengini değiştirmeyi kolaylaştırır', 'Parçanın patentini otomatik olarak sağlar'], 'Simetrik parçada işçinin yön bulmasına gerek kalmaz; asimetri zorunluysa belirgin yapılarak yanlış takma engellenir.'),
  ('Bir CNC tezgâhında işlenen parçada delik konumları teknik resimde verilen ölçülerden sürekli aynı yönde 0,1 mm kayık çıkıyor. En olası neden hangisidir?', 'Tezgâhın sıfır noktası kaymış', ['Rastgele titreşimler', 'Operatörün ekranı yanlış okuması ve not alması', 'Malzemenin rengi'], 'Bütün konumların aynı yönde ve miktarda kayması sistematik bir hatayı, örneğin iş parçası sıfırının yanlış alınmasını düşündürür.'),
  ('Bir ölçü aletinin seçiminde sık kullanılan \'onda bir kuralı\' neyi önerir?', 'Alet çözünürlüğü toleransın onda biri olmalı', ['Aletin fiyatı parçanın onda biri olmalıdır', 'Her ölçüm on kez tekrarlanmalıdır', 'Alet on yılda bir, yetkili bir laboratuvarda kalibre edilmelidir'], 'Örneğin ±0,05 mm (toplam 0,1 mm) toleranslı bir ölçü için en az 0,01 mm çözünürlüklü alet seçilmelidir; böylece aletin katkısı küçük kalır.'),
  ('Hava sıcaklığı, nem ve titreşimin kontrol altında tutulduğu ölçüm odalarının amacı nedir?', 'Çevresel etkileri en aza indirmek', ['Çalışanların rahat etmesini tek amaç saymak', 'Parçaların daha hızlı paslanmasını sağlamak', 'Aletlerin daha az kalibrasyon gerektirmesini garanti etmek'], 'Isıl genleşme, nem ve titreşim hassas ölçümde önemli hata kaynaklarıdır; metroloji laboratuvarları bu yüzden iklimlendirilir.'),
  ('Bir termometrenin cam haznesi ölçülen sıvıya batırıldıktan hemen sonra okunuyor. Bu durum hangi hataya yol açabilir?', 'Isıl denge kurulmadan okuma hatası', ['Paralaks hatasının tamamen ortadan kalkması', 'Termometrenin kendiliğinden kalibre olması', 'Sıvının sıcaklığının termometreye göre değişmemesi'], 'Algılayıcının ortamla ısıl dengeye gelmesi zaman alır (zaman sabiti); erken okuma gerçek sıcaklıktan farklı değer verir.'),
  ('Bir tasarım ekibi, gereksinimleri \'olmalı\' (must) ve \'olsa iyi olur\' (want) diye ikiye ayırıyor. Bu ayrımın kavram seçimindeki işlevi nedir?', 'Olmalılar eler, iyi olurlar sıralar', ['İki grubu da yalnız puanlamada eşit ağırlıkla kullanmak', 'Olmalıları yok sayıp yalnız isteklere bakmak', 'Tüm gereksinimleri müşteriye yeniden yazdırmak'], 'Zorunlu gereksinimi karşılamayan kavram doğrudan elenir; kalan kavramlar istek ölçütleriyle karşılaştırılır.'),
  ('Bir karar matrisinde düşük maliyet istenen \'maliyet\' ölçütü puanlanırken nelere dikkat edilmelidir?', 'Ucuz seçenek yüksek puan almalı', ['Pahalı seçenek yüksek puan almalı', 'Maliyet ölçütü matrise hiç eklenmemeli', 'Maliyet puanı her kavram için aynı verilmeli'], 'Tüm ölçütlerde \'yüksek puan = daha iyi\' olacak biçimde ölçek kurulmalıdır; aksi hâlde toplam puan yanıltır.'),
  ('Bir ürünün kullanılabilirlik testinde katılımcılardan düşündüklerini sesli söylemeleri isteniyor. Bu yöntemin adı nedir?', 'Sesli düşünme protokolü', ['Çift kör klinik deney', 'Hızlandırılmış ömür testi', 'Tahribatlı malzeme deneyi'], 'Sesli düşünmede kullanıcı görevleri yaparken aklından geçenleri anlatır; tasarımcı kafa karışıklığı yaşanan anları doğrudan görür.'),
  ('A/B testi bir tasarım kararında nasıl kullanılır?', 'İki sürüm ayrı kullanıcı gruplarında denenir', ['Tasarım yalnız A ve B harfli parçalarla yapılır', 'İki mühendis aynı tasarımı ayrı ayrı çizer', 'Ürün önce A ülkesinde, sonra B ülkesinde satılır'], 'Kullanıcılar rastgele iki gruba ayrılıp farklı sürümleri kullanır; ölçülen davranış farkı hangi tasarımın daha iyi olduğunu gösterir.'),
  ('Bir tasarım ekibi \'en küçük uygulanabilir ürün\' (MVP) ile piyasaya çıkıyor. Bu yaklaşımın amacı nedir?', 'Az kaynakla gerçek kullanıcıdan erken geri bildirim almak', ['Ürünü olabilecek en düşük kaliteyle sonsuza dek satmak', 'Tüm özellikleri ilk sürümde eksiksiz ve kusursuz olarak sunmak', 'Kullanıcı görüşlerini tamamen dışarıda bırakmak'], 'MVP, temel değeri sunan en yalın sürümdür; ekip öğrendiklerine göre ürünü geliştirir.'),
  ('Sistem mühendisliğinde \'V modeli\' neyi vurgular?', 'Her tasarım düzeyinin bir test düzeyiyle eşleşmesini', ['Ürünün V harfi biçiminde tasarlanmasını', 'Projenin yalnız iki aşamadan oluşmasını', 'Testin yalnız proje sonunda, tek bir kabul aşamasında yapılmasını'], 'V\'nin sol kolu gereksinimden ayrıntılı tasarıma iner; sağ kolu bileşen testinden sistem kabul testine çıkar ve her düzey karşısındakini doğrular.'),
  ('Bir sistemin ortalama arızalar arası süresi (MTBF) 2000 saattir. Bu değer için hangi yorum doğrudur?', 'Ortalama olarak 2000 saatte bir arıza beklenir', ['Sistem kesinlikle 2000 saatten önce arızalanmaz', 'Sistem tam 2000. saatte arızalanır', 'Sistem 2000 saat sonra hiç arızalanmaz'], 'MTBF istatistiksel bir ortalamadır; tek bir ürünün ne zaman arızalanacağını kesin olarak söylemez.'),
  ('Kritik bir sistemde aynı işlevi farklı ilkelerle çalışan iki ayrı birimin görmesine ne ad verilir?', 'Çeşitlendirilmiş yedeklilik', ['Planlı eskitme', 'Tek nokta arızası', 'Değer mühendisliğiyle parça azaltma'], 'Farklı tasarımlı yedekler ortak nedenli arızalara (aynı yazılım hatası gibi) karşı aynı birimlerin çoğaltılmasından daha iyi koruma sağlar.'),
  ('Bir tasarımda arızalandığında tüm sistemi durduran ve yedeği olmayan bileşene ne ad verilir?', 'Tek nokta arızası', ['Yedekli bileşen', 'Paralel bileşen', 'Arızaya dayanıklı alt sistem'], 'Tek nokta arızaları güvenilirlik analizinde öncelikle aranır; yedekleme ya da tasarım değişikliğiyle ortadan kaldırılmaya çalışılır.'),
  ('Bilişsel ergonomi açısından bir uçak kokpitinde benzer görünen iki şalterin yan yana konmasının riski nedir?', 'Karıştırılıp yanlış şalterin kullanılması', ['Şalterlerin daha hızlı aşınması', 'Kokpitin daha ağır olması', 'Şalterlerin hiç elektrik tüketmemesi ve sessiz kalması'], 'İkinci Dünya Savaşı\'nda bazı uçaklarda iniş takımı ve flap kollarının karıştırılması, kumandaların biçimle ayırt edilmesi (şekil kodlaması) fikrine yol açtı.'),
  ('Bir lamba tasarımında akkor ampul yerine LED kullanılması yaşam döngüsü açısından en çok hangi aşamada etkiyi azaltır?', 'Kullanım aşamasındaki enerji tüketimi', ['Hammadde çıkarma aşamasında', 'Ambalaj üretiminde', 'Fabrikadan mağazaya kara yoluyla taşımada'], 'Aydınlatma ürünlerinde toplam çevresel etkinin büyük bölümü kullanım sırasındaki elektrik tüketiminden gelir; LED aynı ışığı çok daha az enerjiyle verir.'),
  ('Bir ölçüm sisteminin \'tekrarlanabilirlik\' ve \'yeniden üretilebilirlik\' özellikleri arasındaki fark nedir?', 'Aynı koşul ve kişi / farklı kişi, alet ya da yer', ['İkisi de yalnız sıcaklıkla ilgilidir', 'Tekrarlanabilirlik yalnız dijital aletlerde, ötekisi analoglarda geçerlidir', 'Biri doğruluğu, öteki fiyatı ölçer'], 'Tekrarlanabilirlik aynı koşullarda art arda ölçümlerin tutarlılığıdır; yeniden üretilebilirlik farklı operatör, alet ya da laboratuvarlar arasındaki tutarlılıktır.'),
  ('Bir öğrenci sarkaç periyodunu ölçerken tek salınımı değil 20 salınımın toplam süresini ölçüp 20\'ye bölüyor. Bu yöntemin yararı nedir?', 'Kronometre tepki hatasının etkisi azalır', ['Sarkacın gerçek periyodu değişir', 'Ölçüm daha kısa sürer', 'Ölçümde hiçbir sistematik ya da rastgele hata kalmaz'], 'Başlatma-durdurma hatası toplam süreye bir kez eklenir; 20\'ye bölününce periyottaki payı yirmide birine iner.'),
  ('Bir terazinin ekranında okunan değer tartım sırasında son basamakta ±1 dalgalanıyor. Bu dalgalanma büyük olasılıkla neyi yansıtır?', 'Rastgele ölçüm gürültüsünü', ['Kütlenin sürekli değiştiğini', 'Terazinin kesin olarak bozuk olduğunu', 'Sistematik bir sıfır hatasını'], 'Son basamaktaki küçük, iki yönlü dalgalanmalar hava akımı, titreşim ve elektronik gürültü gibi rastgele etkilerden kaynaklanır.'),
  ('Pekleşmiş bir bakır teli yeniden yumuşatmak için hangi işlem uygulanır?', 'Yeniden kristalleşme tavı', ['Su verme ve ardından sert kaplama', 'Bilyeli dövme', 'Soğuk haddeleme ile ikinci kez inceltme'], 'Uygun sıcaklıkta tavlama yeni, gerinimsiz taneler oluşturur; süneklik geri kazanılır.'),
  ('Seramiklerin çoğunun elektrik yalıtkanı olmasının nedeni nedir?', 'Serbest elektron yoktur', ['Atomlarının çok hafif olması', 'Yoğunluklarının çok yüksek olması', 'Kristal yapılarının her zaman kübik olması ve ışığı geçirmesi'], 'İyonik ve kovalent bağlarda elektronlar atomlara ya da bağlara sıkıca bağlıdır; bu yüzden porselen yalıtkanlar elektrik hatlarında kullanılır.'),
  ('Bir malzemenin ısıl şoka direnci genellikle hangi özellik karmasıyla artar?', 'Yüksek iletkenlik ve dayanım, düşük genleşme', ['Düşük ısıl iletkenlik ve yüksek ısıl genleşme', 'Yüksek yoğunluk ve düşük dayanım', 'Koyu renk ve yüksek özgül ısı'], 'Isıyı hızla dağıtan, az genleşen ve dayanımı yüksek malzemelerde ani sıcaklık değişiminin yarattığı gerilmeler kırılmaya daha az yol açar.'),
  ('Girdap akımı muayenesi hangi malzemelerde uygulanabilir?', 'Elektriği ileten malzemelerde', ['Yalnız camda', 'Yalnız ahşapta', 'Elektrik iletmeyen plastik ve seramiklerde'], 'Bobinin oluşturduğu değişken manyetik alan iletken malzemede girdap akımları doğurur; çatlaklar bu akımları bozar ve bobin empedansı değişir.'),
  ('Bir uçak motoru içindeki türbin kanatlarını sökmeden görsel olarak incelemek için kullanılan ince optik alet hangisidir?', 'Boroskop', ['Mikrometre', 'Durometre', 'Charpy sarkacı'], 'Boroskop, ince bir boru ya da esnek kabloyla dar boşluklara girip iç yüzeyleri görüntüler.'),
  ('Mühendislik etik kurallarının hukuktan farkı en iyi nasıl açıklanır?', 'Asgari yasal zorunluluğun ötesine geçen mesleki standartlardır', ['Etik kurallar yalnız ceza hukukunu kapsar', 'Etik kurallar her zaman yasalardan daha gevşektir', 'Etik kurallar yalnız şirket yöneticileri için yazılır ve mühendisleri bağlamaz'], 'Meslek etiği, yasal zorunluluğu olmayan konularda da (örneğin dürüstlük, yetkinlik) mühendisten yüksek bir davranış standardı bekler.'),
  ('Bir mühendisin, müşterisinin bilgisi olmadan bir alt yükleniciden komisyon alması neden etik dışıdır?', 'Gizli çıkar, müşteri lehine yargıyı bozar', ['Komisyon tutarının vergiye tabi olması nedeniyle', 'Alt yüklenicinin zarar etmesi kesin olduğu için', 'Komisyonun her zaman nakit ödenmesi gerektiği için'], 'Müşteriye açıklanmayan ödemeler, mühendisin müşteri adına tarafsız karar verme görevini tehlikeye atar.'),
  ('Mühendislik etiğinde \'ihmal\' ile \'kasıt\' arasındaki fark nedir?', 'İhmalde özen eksiktir, kasıtta zarar bilerek göze alınır', ['İkisi aynıdır, yalnız mahkemede farklı adlandırılır', 'İhmal yalnız çevreye, kasıt yalnız insanlara verilen zarardır', 'Kasıt her zaman daha az ceza gerektiren hafif bir davranıştır'], 'İhmal, makul bir mühendisin göstereceği özenin gösterilmemesidir; kasıtta ise sonuç bilinerek ya da istenerek davranılır.'),
  ('Bir şirketin baraj projesi için yapılan çevresel etki değerlendirmesinin (ÇED) temel amacı nedir?', 'Olası çevresel etkileri karar öncesinde belirlemek', ['Projenin inşaat maliyetini kesin olarak hesaplamak', 'Barajın adını ve açılış tarihini belirlemek', 'Projeye itiraz edenlerin listesini çıkarmak ve yayımlamak'], 'ÇED, projenin ekosistem, su kaynakları ve topluluklar üzerindeki etkilerini önceden inceleyip önlemleri ve seçenekleri ortaya koyar.'),
  ('Bir mühendis, yalnız kendi ülkesinin değil ürünün satılacağı ülkelerin standartlarını da araştırıyor. Bunun en önemli nedeni nedir?', 'Güvenlik ve yasal gereklilikler ülkeye göre değişir', ['Yabancı standartların her zaman daha ucuz olması', 'Kendi ülkesinin standartlarının yasaklı olması', 'Ürünün rengi ülkeye göre zorunlu olarak değişir ve tescil edilir'], 'Elektrik gerilimi, işaretleme, malzeme kısıtları gibi gereklilikler pazara göre farklıdır; uyumsuz ürün güvenlik riski ve yasal sorun doğurur.'),
];
